window.QB_POOLS=window.QB_POOLS||{};window.QB_POOLS["q60bede4a3a"]={"type":"政治常识","questions":[{"qid":"sy-b-20240330-002","no":2,"type":"政治常识","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"政治常识","tag":"未细分","confidence":"待复核","needsReview":true,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.unresolved","evidence":"体现效率与公平关系的是（ ）。","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[1],"answer":[1,2]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-b-20240330-002-题目-p01-208-331.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"加快构建以国内大循环为主体，国内国际双循环相互促进的新发展格局"},{"k":"B","t":"通过集聚科技资源和人才资源，用好用活国际国内两种科技资源，推动科技强国建设"},{"k":"C","t":"要先把“蛋糕”做大，然后通过合理的制度安排把“蛋糕”分好，水涨船高、各得其所"},{"k":"D","t":"面对新形势、新情况，必须力戒刻舟求剑，守株待兔，修炼真本领，崇尚创新、勇于创新"}],"answer":"C","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-b-20240330-002-解析-p01-415-812.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-b-20240330-002-解析-p02-51-262.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"推进中国式现代化是一个系统工程，需要统筹兼顾、系统谋划、整体推进，正确处理好顶层设计与实践探索、战略与策略、守正与创新、效率与公平、活力与秩序、自立自强与对外开放等一系列重大关系。下列选项中，体现效率与公平关系的是（ ）。","options":[{"k":"A","t":"加快构建以国内大循环为主体，国内国际双循环相互促进的新发展格局"},{"k":"B","t":"通过集聚科技资源和人才资源，用好用活国际国内两种科技资源，推动科技强国建设"},{"k":"C","t":"要先把“蛋糕”做大，然后通过合理的制度安排把“蛋糕”分好，水涨船高、各得其所"},{"k":"D","t":"面对新形势、新情况，必须力戒刻舟求剑，守株待兔，修炼真本领，崇尚创新、勇于创新"}],"material":"","explanation":"2、本题考查政治常识。\n\n2023 年10 月1 日，第19 期《求是》杂志发表了总书记的重要文章《推进中国式现代化需要处理好若干重大关系》。文章指出，推进中国式现代化是一个系统工程，需要统筹兼顾、系统谋划、整体推进，正确处理好一系列重大关系。文章重点强调了6 个方面：一是顶层设计与实践探索的关系。二是战略与策略的关系。\n\n三是守正与创新的关系。四是效率与公平的关系。五是活力与秩序的关系。六是自立自强与对外开放的关系。\n\nA 项错误，“加快构建以国内大循环为主体，国内国际双循环相互促进的新发展格局”体现的是自立自强与对外开放的关系。\n\nB 项错误，“用好用活国际国内两种科技资源”体现的是自立自强与对外开放的关系。\n\nC 项正确，“先把‘蛋糕’做大，然后把‘蛋糕’分好”指的是，实现共同富裕目标，首先要通过全国人民共同奋斗把“蛋糕”做大做好，然后通过合理的制度安排把“蛋糕”切好分好。这体现的是效率与公平关系。\n\nD 项错误，“崇尚创新、勇于创新”体现的是守正与创新的关系。\n\n故正确答案为C。"},"from":{"file":"07-事业编职测/B类/2024/2024-03-30/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"政治常识","questionPages":[1],"answerPages":[1,2]},"idx":1,"pid":"pb8bf388b20","sourceYears":[2024]},{"qid":"sy-c-20240330-001","no":1,"type":"政治常识","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"政治常识","tag":"未细分","confidence":"待复核","needsReview":true,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.unresolved","evidence":"体现效率与公平关系的是（ ）。","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[1],"answer":[1]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20240330-001-题目-p01-106-229.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"加快构建以国内大循环为主体，国内国际双循环相互促进的新发展格局"},{"k":"B","t":"通过集聚科技资源和人才资源，用好用活国际国内两种科技资源，推动科技强国建设"},{"k":"C","t":"要先把“蛋糕”做大，然后通过合理的制度安排把“蛋糕”分好，水涨船高、各得其所"},{"k":"D","t":"面对新形势、新情况，必须力戒刻舟求剑，守株待兔，修炼真本领，崇尚创新、勇于创新"}],"answer":"C","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20240330-001-解析-p01-129-477.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"推进中国式现代化是一个系统工程，需要统筹兼顾、系统谋划、整体推进，正确处理好顶层设计与实践探索、战略与策略、守正与创新、效率与公平、活力与秩序、自立自强与对外开放等一系列重大关系。下列选项中，体现效率与公平关系的是（ ）。","options":[{"k":"A","t":"加快构建以国内大循环为主体，国内国际双循环相互促进的新发展格局"},{"k":"B","t":"通过集聚科技资源和人才资源，用好用活国际国内两种科技资源，推动科技强国建设"},{"k":"C","t":"要先把“蛋糕”做大，然后通过合理的制度安排把“蛋糕”分好，水涨船高、各得其所"},{"k":"D","t":"面对新形势、新情况，必须力戒刻舟求剑，守株待兔，修炼真本领，崇尚创新、勇于创新"}],"material":"","explanation":"1、本题考查政治常识。\n\n2023 年10 月1 日，第19 期《求是》杂志发表了总书记的重要文章《推进中国式现代化需要处理好若干重大关系》。文章指出，推进中国式现代化是一个系统工程，需要统筹兼顾、系统谋划、整体推进，正确处理好一系列重大关系。文章重点强调了6 个方面：一是顶层设计与实践探索的关系。二是战略与策略的关系。\n\n三是守正与创新的关系。四是效率与公平的关系。五是活力与秩序的关系。六是自立自强与对外开放的关系。\n\nA 项错误，“加快构建以国内大循环为主体，国内国际双循环相互促进的新发展格局”体现的是自立自强与对外开放的关系。\n\nB 项错误，“用好用活国际国内两种科技资源”体现的是自立自强与对外开放的关系。\n\nC 项正确，“先把‘蛋糕’做大，然后把‘蛋糕’分好”指的是，实现共同富裕目标，首先要通过全国人民共同奋斗把“蛋糕”做大做好，然后通过合理的制度安排把“蛋糕”切好分好。这体现的是效率与公平关系。\n\nD 项错误，“崇尚创新、勇于创新”体现的是守正与创新的关系。\n\n故正确答案为C。"},"from":{"file":"07-事业编职测/C类/2024/2024-03-30/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"政治常识","questionPages":[1],"answerPages":[1]},"idx":0,"pid":"p3f16ff5043","sourceYears":[2024]},{"qid":"sy-a-20241102-006","no":6,"type":"政治常识","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"政治常识","tag":"未细分","confidence":"待复核","needsReview":true,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.unresolved","evidence":"是：","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[3],"answer":[2,3]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-a-20241102-006-题目-p03-108-244.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"向党的任何机关提出建议是党员的权利之一"},{"k":"B","t":"中国共产党以毛泽东思想作为一切工作的指针"},{"k":"C","t":"第一次明确规定党部的指导原则为民主集中制"},{"k":"D","t":"党的性质是中国工人阶级的先进的有组织的部队"}],"answer":"C","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-a-20241102-006-解析-p02-647-812.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-a-20241102-006-解析-p03-51-156.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"（单选题）党的七大通过的《中国共产党党章》是党成熟的重要标志，下列不属于中共七大党章内容的是：","options":[{"k":"A","t":"向党的任何机关提出建议是党员的权利之一"},{"k":"B","t":"中国共产党以毛泽东思想作为一切工作的指针"},{"k":"C","t":"第一次明确规定党部的指导原则为民主集中制"},{"k":"D","t":"党的性质是中国工人阶级的先进的有组织的部队"}],"material":"","explanation":"6\n\n本题考查政治常识。\n\nA项正确，中共七大首次在党章中规定党员的权利和义务，各有四项。其中权利为：在党的会议或党的刊物上，参加关于党的政策的实施问题自由的讨论；党内的选举权和被选举权；向党的任何机关直至中央提出建议和声明；在党的会议上批评党的任何工作人员。\n\nB项正确，中共七大通过的党章明确指出，中国共产党以马克思列宁主义的理论与中国革命的实践之统一的思想——毛泽东思想，作为自己一切工作的指针。中共七大第一次将毛泽东思想确立为党的指导思想写进党章，这是马克思主义中国化的第一次历史性飞跃。\n\n2024/12/31 10:58\n\nC项错误，五大党章第一次在组织原则和组织制度方面，明确规定“党部的指导原则为民主集中制”，这是从党的根本法规的高度第一次出现民主集中制的提法。七大进一步完善了党的民主集中制，科学界定了民主集中制的内涵，即在民主的基础上的集中和在集中指导下的民主，提出了坚持民主集中制的“四个服从”。\n\nD项正确，七大党章首次增写总纲部分，阐明了党的性质、纲领、宗旨、作风、群众路线，从而使党章具备了完整的理论形态。其中明确指出，党的性质是中国工人阶级的先进的有组织的部队。\n\n本题为选非题，故正确答案为C。"},"from":{"file":"07-事业编职测/A类/2024/2024-11-02/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"政治常识","questionPages":[3],"answerPages":[2,3]},"idx":5,"pid":"p278ae760c2","sourceYears":[2024]},{"qid":"sy-a-20230507-001","no":1,"type":"政治常识","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"政治常识","tag":"未细分","confidence":"待复核","needsReview":true,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.unresolved","evidence":"④实现了马克思主义中国化时代化新的飞跃","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[1],"answer":[1]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-a-20230507-001-题目-p01-116-292.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"1"},{"k":"B","t":"2"},{"k":"C","t":"3"},{"k":"D","t":"4"}],"answer":"D","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-a-20230507-001-解析-p01-104-358.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"党的二十大报告系统总结了十八大以来党和国家事业取得的历史性成就、发生的历史性变革。对此，下列说法正确的有几项？（ ）\n\n①全面依法治国总体格局基本形成\n\n②建成世界上规模最大的社会保障体系\n\n③共建共治共享的社会治理制度进一步健全\n\n④实现了马克思主义中国化时代化新的飞跃","options":[{"k":"A","t":"1"},{"k":"B","t":"2"},{"k":"C","t":"3"},{"k":"D","t":"4"}],"material":"","explanation":"1\n\n本题考查政治常识。\n\n①项正确，党的二十大报告指出，社会主义法治国家建设深入推进，全面依法治国总体格局基本形成，中国特色社会主义法治体系加快建设，司法体制改革取得重大进展，社会公平正义保障更为坚实，法治中国建设开创新局面。\n\n②项正确，党的二十大报告指出，建成世界上规模最大的教育体系、社会保障体系、医疗卫生体系，教育普及水平实现历史性跨越，基本养老保险覆盖十亿四千万人，基本医疗保险参保率稳定在百分之九十五。\n\n③项正确，党的二十报告指出，共建共治共享的社会治理制度进一步健全，民族分裂势力、宗教极端势力、暴力恐怖势力得到有效遏制，扫黑除恶专项斗争取得阶段性成果，有力应对一系列重大自然灾害，平安中国建设迈向更高水平。\n\n④项正确，党的二十大报告指出，我们创立了新时代中国特色社会主义思想，明确坚持和发展中国特色社会主义的基本方略，提出一系列治国理政新理念新思想新战略，实现了马克思主义中国化时代化新的飞跃，坚持不懈用这一创新理论武装头脑、指导实践、推动工作，为新时代党和国家事业发展提供了根本遵循。\n\n因此①②③④正确。\n\n故正确答案为D。"},"from":{"file":"07-事业编职测/A类/2023/2023-05-07/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"政治常识","questionPages":[1],"answerPages":[1]},"idx":0,"pid":"padb6c2718d","sourceYears":[2023]},{"qid":"sy-a-20230507-002","no":2,"type":"政治常识","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"政治常识","tag":"未细分","confidence":"待复核","needsReview":true,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.unresolved","evidence":"党的二十大报告提出，发展全过程人民民主，保障人民当家作主。对此，下列说法错误的是（ ）。","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[1],"answer":[1]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-a-20230507-002-题目-p01-288-386.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"坚持走中国人权发展道路，积极参与全球人权治理"},{"k":"B","t":"健全以职工代表大会为基本形式的企事业单位民主管理制度"},{"k":"C","t":"支持和保证人民通过基层自治组织和社会团体行使国家权力"},{"k":"D","t":"保证各级人大都由民主选举产生、对人民负责、受人民监督"}],"answer":"C","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-a-20230507-002-解析-p01-353-530.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"党的二十大报告提出，发展全过程人民民主，保障人民当家作主。对此，下列说法错误的是（ ）。","options":[{"k":"A","t":"坚持走中国人权发展道路，积极参与全球人权治理"},{"k":"B","t":"健全以职工代表大会为基本形式的企事业单位民主管理制度"},{"k":"C","t":"支持和保证人民通过基层自治组织和社会团体行使国家权力"},{"k":"D","t":"保证各级人大都由民主选举产生、对人民负责、受人民监督"}],"material":"","explanation":"本题考查政治常识。\n\nA项正确，党的二十大报告指出，加强人民当家作主制度保障，坚持走中国人权发展道路，积极参与全球人权治理，推动人权事业全面发展。\n\nB项正确，党的二十大报告指出，积极发展基层民主，全心全意依靠工人阶级，健全以职工代表大会为基本形式的企事业单位民主管理制度，维护职工合法权益。\n\nC项错误、D项正确，党的二十大报告指出，加强人民当家作主制度保障，坚持和完善我国根本政治制度、基本政治制度、重要政治制度，拓展民主渠道，丰富民主形式，确保人民依法通过各种途径和形式管理国家事务，管理经济和文化事业，管理社会事务。支持和保证人民通过人民代表大会行使国家权力，保证各级人大都由民主选举产生、对人民负责、受人民监督。故C项“支持和保证人民通过基层自治组织和社会团体行使国家权力”说法错误。\n\n本题为选非题，故正确答案为C。"},"from":{"file":"07-事业编职测/A类/2023/2023-05-07/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"政治常识","questionPages":[1],"answerPages":[1]},"idx":1,"pid":"padb6c2718d","sourceYears":[2023]},{"qid":"sy-a-20230507-003","no":3,"type":"政治常识","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"政治常识","tag":"未细分","confidence":"待复核","needsReview":true,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.unresolved","evidence":"界观和方法论，坚持好、运用好贯穿其中的立场观点方法。对此，下列选项对应不准确的是（ ）。","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[1],"answer":[1,2]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-a-20230507-003-题目-p01-382-495.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"推进改革发展往往牵一发而动全身——坚持系统观念"},{"k":"B","t":"中国的问题必须由中国人自己来解答——坚持自信自立"},{"k":"C","t":"回答并指导解决问题是理论的根本任务——坚持问题导向"},{"k":"D","t":"人民的创造性实践是理论创新的不竭源泉——坚持守正创新"}],"answer":"D","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-a-20230507-003-解析-p01-525-812.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-a-20230507-003-解析-p02-51-92.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"党的二十大报告提出，继续推进实践基础上的理论创新，首先要把握好新时代中国特色社会主义思想的世界观和方法论，坚持好、运用好贯穿其中的立场观点方法。对此，下列选项对应不准确的是（ ）。","options":[{"k":"A","t":"推进改革发展往往牵一发而动全身——坚持系统观念"},{"k":"B","t":"中国的问题必须由中国人自己来解答——坚持自信自立"},{"k":"C","t":"回答并指导解决问题是理论的根本任务——坚持问题导向"},{"k":"D","t":"人民的创造性实践是理论创新的不竭源泉——坚持守正创新"}],"material":"","explanation":"3\n\n本题考查政治常识。\n\nA项正确，党的二十大报告指出，必须坚持系统观念。万事万物是相互联系、相互依存的。只有用普遍联系的、全面系统的、发展变化的观点观察事物，才能把握事物发展规律。我国是一个发展中大国，仍处于社会主义初级阶段，正在经历广泛而深刻的社会变革，推进改革发展、调整利益关系往往牵一发而动全身。\n\nB项正确，党的二十大报告指出，必须坚持自信自立。中国人民和中华民族从近代以后的深重苦难走向伟大复兴的光明前景，从来就没有教科书，更没有现成答案。党的百年奋斗成功道路是党领导人民独立自主探索开辟出来的，马克思主义的中国篇章是中国共产党人依靠自身力量实践出来的，贯穿其中的一个基本点就是中国的问题必须从中国基本国情出发，由中国人自己来解答。\n\nC项正确，党的二十大报告指出，必须坚持问题导向。问题是时代的声音，回答并指导解决问题是理论的根本任务。今天我们所面临问题的复杂程度、解决问题的艰巨程度明显加大，给理论创新提出了全新要求。\n\nD项错误，党的二十大报告指出，必须坚持人民至上。人民性是马克思主义的本质属性，党的理论是来自人民、为了人民、造福人民的理论，人民的创造性实践是理论创新的不竭源泉。一切脱离人民的理论都是苍白无力的，一切不为人民造福的理论都是没有生命力的。故“人民的创造性实践是理论创新的不竭源泉一一坚持守正创新”说法错误。\n\n本题为选非题，故正确答案为D。"},"from":{"file":"07-事业编职测/A类/2023/2023-05-07/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"政治常识","questionPages":[1],"answerPages":[1,2]},"idx":2,"pid":"padb6c2718d","sourceYears":[2023]},{"qid":"sy-a-20230507-004","no":4,"type":"政治常识","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"政治常识","tag":"未细分","confidence":"待复核","needsReview":true,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.unresolved","evidence":"④免除经济困难高校毕业生2022 年国家助学贷款利息并允许延期还本","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[1],"answer":[2]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-a-20230507-004-题目-p01-491-667.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"①③"},{"k":"B","t":"①④"},{"k":"C","t":"②③"},{"k":"D","t":"②④"}],"answer":"D","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-a-20230507-004-解析-p02-88-326.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"2023 年3 月5 日，十四届全国人大一次会议上的《政府工作报告》对过去一年的工作进行了回顾。下列与之相关的说法正确的是（ ）。\n\n①货物进出口好于预期，实际使用外资有所下降\n\n②新发放企业贷款平均利率降至有统计以来最低水平\n\n③向更多中等收入群众发放价格补贴，约6700 万人受益\n\n④免除经济困难高校毕业生2022 年国家助学贷款利息并允许延期还本","options":[{"k":"A","t":"①③"},{"k":"B","t":"①④"},{"k":"C","t":"②③"},{"k":"D","t":"②④"}],"material":"","explanation":"4\n\n本题考查政治常识。\n\n①错误，《政府工作报告》指出：“帮助外贸企业解决原材料、用工、物流等难题，提升港口集疏运效率，及时回应和解决外资企业关切，货物进出口好于预期，实际使用外资稳定增长。”\n\n②正确，《政府工作报告》指出：“引导金融机构增加信贷投放，降低融资成本，新发放企业贷款平均利率降至有统计以来最低水平，对受疫情影响严重的中小微企业、个体工商户和餐饮、旅游、货运等实施阶段性贷款延期还本付息，对普惠小微贷款阶段性减息。”\n\n③错误，《政府工作报告》指出：“针对部分群众生活困难增多，强化基本民生保障。阶段性扩大低保等社会保障政策覆盖面，将更多困难群体纳入保障范围。延续实施失业保险保障扩围政策，共向1000多万失业人员发放失业保险待遇。向更多低收入群众发放价格补贴，约6700万人受益。”\n\n④正确，《政府工作报告》指出：“免除经济困难高校毕业生2022年国家助学贷款利息并允许延期还本。\n\n做好因疫因灾遇困群众临时救助工作，切实兜住民生底线。”综上所述，①③错误，②④正确。\n\n故正确答案为D。"},"from":{"file":"07-事业编职测/A类/2023/2023-05-07/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"政治常识","questionPages":[1],"answerPages":[2]},"idx":3,"pid":"padb6c2718d","sourceYears":[2023]},{"qid":"sy-a-20230507-005","no":5,"type":"政治常识","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"政治常识","tag":"未细分","confidence":"待复核","needsReview":true,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.unresolved","evidence":"是（ ）。","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[1,2],"answer":[2]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-a-20230507-005-题目-p01-662-812.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-a-20230507-005-题目-p02-51-90.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"组建金融监督管理总局，不再保留中国人民银行"},{"k":"B","t":"组建中央社会工作部，作为党中央议事协调机构"},{"k":"C","t":"组建国家数据局，由国家发展和改革委员会管理"},{"k":"D","t":"按照5%的比例精减中央和地方党政机关人员编制"}],"answer":"C","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-a-20230507-005-解析-p02-322-623.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"2023 年3 月，中共中央、国务院印发了《党和国家机构改革方案》。关于该方案的内容，下列说法正确的是（ ）。","options":[{"k":"A","t":"组建金融监督管理总局，不再保留中国人民银行"},{"k":"B","t":"组建中央社会工作部，作为党中央议事协调机构"},{"k":"C","t":"组建国家数据局，由国家发展和改革委员会管理"},{"k":"D","t":"按照5%的比例精减中央和地方党政机关人员编制"}],"material":"","explanation":"本题考查政治常识。\n\n2023年3月，中共中央、国务院印发了《党和国家机构改革方案》。\n\nA项错误，《党和国家机构改革方案》指出，组建国家金融监督管理总局。国家金融监督管理总局在中国银行保险监督管理委员会基础上组建，将中国人民银行对金融控股公司等金融集团的日常监管职责、有关金融消费者保护职责，中国证券监督管理委员会的投资者保护职责划入国家金融监督管理总局。不再保留中国银行保险监督管理委员会。故“不再保留中国人民银行”说法错误。\n\nB项错误，《党和国家机构改革方案》指出，组建中央社会工作部。负责统筹指导人民信访工作，指导人民建议征集工作，统筹推进党建引领基层治理和基层政权建设，统一领导全国性行业协会商会党的工作，协调推动行业协会商会深化改革和转型发展，指导混合所有制企业、非公有制企业和新经济组织、新社会组织、新就业群体党建工作，指导社会工作人才队伍建设等，作为党中央职能部门。故“作为党中央议事协调机构”说法错误。\n\nC项正确，《党和国家机构改革方案》指出，组建国家数据局。负责协调推进数据基础制度建设，统筹数据资源整合共享和开发利用，统筹推进数字中国、数字经济、数字社会规划和建设等，由国家发展和改革委员会管理。\n\nD项错误，《党和国家机构改革方案》指出，精减中央和国家机关人员编制。中央和国家机关各部门人员编制统一按照5%的比例进行精减，收回的编制主要用于加强重点领域和重要工作。中央垂管派出机构、驻外机构不纳入统一精减范围，根据行业和系统实际，盘活用好存量编制资源。故“按照5%的比例精减地方党政机关人员编制”说法错误。\n\n故正确答案为C。"},"from":{"file":"07-事业编职测/A类/2023/2023-05-07/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"政治常识","questionPages":[1,2],"answerPages":[2]},"idx":4,"pid":"padb6c2718d","sourceYears":[2023]},{"qid":"sy-b-20230507-001","no":1,"type":"政治常识","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"政治常识","tag":"未细分","confidence":"待复核","needsReview":true,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.unresolved","evidence":"（ ）。","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[1],"answer":[1]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-b-20230507-001-题目-p01-116-230.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"打赢了人类历史上规模最大的脱贫攻坚战"},{"k":"B","t":"货物贸易总额和吸引外资均高居世界第一"},{"k":"C","t":"我国经济总量占世界经济的比重超过30%"},{"k":"D","t":"全国居民人均可支配收入历史性突破6 万元"}],"answer":"A","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-b-20230507-001-解析-p01-104-357.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"党的二十大报告系统总结了十八大以来党和国家事业取得的历史性成就。对此，下列说法正确的是（ ）。","options":[{"k":"A","t":"打赢了人类历史上规模最大的脱贫攻坚战"},{"k":"B","t":"货物贸易总额和吸引外资均高居世界第一"},{"k":"C","t":"我国经济总量占世界经济的比重超过30%"},{"k":"D","t":"全国居民人均可支配收入历史性突破6 万元"}],"material":"","explanation":"1\n\n本题考查政治常识。\n\nA项正确，党的二十大报告指出，我们经过接续奋斗，实现了小康这个中华民族的千年梦想，我国发展站在了更高历史起点上。我们坚持精准扶贫、尽锐出战，打赢了人类历史上规模最大的脱贫攻坚战，全国八百三十二个贫困县全部摘帽，近一亿农村贫困人口实现脱贫，九百六十多万贫困人口实现易地搬迁，历史性地解决了绝对贫困问题，为全球减贫事业作出了重大贡献。\n\nB项错误，党的二十大报告指出，我国成为一百四十多个国家和地区的主要贸易伙伴，货物贸易总额居世界第一，吸引外资和对外投资居世界前列，形成更大范围、更宽领域、更深层次对外开放格局。故“吸引外资居世界第一”说法错误。\n\nC项错误，党的二十大报告指出，国内生产总值从五十四万亿元增长到一百一十四万亿元，我国经济总量占世界经济的比重达百分之十八点五，提高七点二个百分点，稳居世界第二位。故“我国经济总量占世界经济的比重超过30%”说法错误。\n\nD项错误，党的二十大报告指出，居民人均可支配收入从一万六千五百元增加到三万五千一百元。故“全国居民人均可支配收入历史性突破6万元”说法错误。\n\n故正确答案为 A。"},"from":{"file":"07-事业编职测/B类/2023/2023-05-07/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"政治常识","questionPages":[1],"answerPages":[1]},"idx":0,"pid":"p8da11424e5","sourceYears":[2023]},{"qid":"sy-b-20230507-002","no":2,"type":"政治常识","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"政治常识","tag":"未细分","confidence":"待复核","needsReview":true,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.unresolved","evidence":"是（ ）。","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[1],"answer":[1]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-b-20230507-002-题目-p01-226-339.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"组建金融监督管理总局，不再保留中国人民银行"},{"k":"B","t":"组建中央社会工作部，作为党中央议事协调机构"},{"k":"C","t":"组建国家数据局，由国家发展和改革委员会管理"},{"k":"D","t":"按照5%的比例精减中央和地方党政机关人员编制"}],"answer":"C","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-b-20230507-002-解析-p01-352-654.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"2023 年3 月，中共中央、国务院印发了《党和国家机构改革方案》。关于该方案的内容，下列说法正确的是（ ）。","options":[{"k":"A","t":"组建金融监督管理总局，不再保留中国人民银行"},{"k":"B","t":"组建中央社会工作部，作为党中央议事协调机构"},{"k":"C","t":"组建国家数据局，由国家发展和改革委员会管理"},{"k":"D","t":"按照5%的比例精减中央和地方党政机关人员编制"}],"material":"","explanation":"本题考查政治常识。\n\n2023年3月，中共中央、国务院印发了《党和国家机构改革方案》。\n\nA项错误，《党和国家机构改革方案》指出，组建国家金融监督管理总局。国家金融监督管理总局在中国银行保险监督管理委员会基础上组建，将中国人民银行对金融控股公司等金融集团的日常监管职责、有关金融消费者保护职责，中国证券监督管理委员会的投资者保护职责划入国家金融监督管理总局。不再保留中国银行保险监督管理委员会。故“不再保留中国人民银行”说法错误。\n\nB项错误，《党和国家机构改革方案》指出，组建中央社会工作部。负责统筹指导人民信访工作，指导人民建议征集工作，统筹推进党建引领基层治理和基层政权建设，统一领导全国性行业协会商会党的工作，协调推动行业协会商会深化改革和转型发展，指导混合所有制企业、非公有制企业和新经济组织、新社会组织、新就业群体党建工作，指导社会工作人才队伍建设等，作为党中央职能部门。故“作为党中央议事协调机构”说法错误。\n\nC项正确，《党和国家机构改革方案》指出，组建国家数据局。负责协调推进数据基础制度建设，统筹数据资源整合共享和开发利用，统筹推进数字中国、数字经济、数字社会规划和建设等，由国家发展和改革委员会管理。\n\nD项错误，《党和国家机构改革方案》指出，精减中央和国家机关人员编制。中央和国家机关各部门人员编制统一按照5%的比例进行精减，收回的编制主要用于加强重点领域和重要工作。中央垂管派出机构、驻外机构不纳入统一精减范围，根据行业和系统实际，盘活用好存量编制资源。故“按照5%的比例精减地方党政机关人员编制”说法错误。\n\n故正确答案为 C。"},"from":{"file":"07-事业编职测/B类/2023/2023-05-07/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"政治常识","questionPages":[1],"answerPages":[1]},"idx":1,"pid":"p8da11424e5","sourceYears":[2023]},{"qid":"sy-b-20230507-004","no":4,"type":"政治常识","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"政治常识","tag":"未细分","confidence":"待复核","needsReview":true,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.unresolved","evidence":"错误的是（ ）。","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[1],"answer":[2]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-b-20230507-004-题目-p01-428-542.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"城市管理网格员可以受理相关群众举报"},{"k":"B","t":"直播销售员属于互联网营销师的工种之一"},{"k":"C","t":"家庭教育指导师可策划家校协同育人活动"},{"k":"D","t":"电子数据取证分析师的工作不包括数据恢复"}],"answer":"D","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-b-20230507-004-解析-p02-244-560.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"近年来，随着我国经济社会发展，人力资源社会保障部公布了一些“新职业”。下列关于新职业的说法，错误的是（ ）。","options":[{"k":"A","t":"城市管理网格员可以受理相关群众举报"},{"k":"B","t":"直播销售员属于互联网营销师的工种之一"},{"k":"C","t":"家庭教育指导师可策划家校协同育人活动"},{"k":"D","t":"电子数据取证分析师的工作不包括数据恢复"}],"material":"","explanation":"4\n\n本题考查政治常识。\n\nA项正确，城市管理网格员是运用现代城市网络化管理技术，巡查、核实、上报、处置市政工程（公用）设施、市容环境、社会管理事务等方面的问题，并对相关信息进行采集、分析、处置的人员。他们的工作任务包括操作信息采集设备，巡查、发现网格内市政工程（公用）设施、市容环境、社会管理事务等方面的问题，受理相关群众举报；操作系统平台对发现或群众举报的网格内市政工程（公用）设施、市容环境、社会管理事务等方面的问题进行核实、上报、记录；研究网格内市政工程（公用）设施、市容环境、社会管理事务等方面问题的立案事宜，提出处置方案；通知存在问题的责任单位，并协助解决相关问题；核实上级通报的问题，协助责任单位处置，并反馈处置结果；收集、整理、分析相关信息、数据，提出网格内城市治理优化建议。\n\nB项正确，互联网营销师有四大工种，即直播销售员、选品员、视频创推员、平台管理员。直播销售员是在直播过程中针对企业产品进行宣传推广，以及进行直接的直播营销人员；选品员是自产品选择、产品卖点提炼、商务谈判、直播流程设计中参与实施管理的人员；视频创推员是通过视频的创作及推广，为后续的直播销售充分预热和赋能，并进一步地开展用户互动工作的人员；平台管理员是针对直播平台进行后台管理，包括账号管理、数据监控，并通过分析指导进一步的直播销售过程的人员。\n\nC项正确，家庭教育指导师是指通过教育学、应用心理学、社会家庭学的理论知识，帮助家庭在夫妻关系、亲子关系、婆媳关系上建立良好的家庭环境，通过改变孩子的生活、学习习惯，建立孩子的德行和责任，帮助家庭幸福的专业人员。家庭教育指导师可以助力家校育人协同发展。\n\nD项错误，电子数据取证分析师是从事电子数据的收集提取、数据恢复及取证分析的人员。电子数据取证分析师的工作包括数据恢复。\n\n本题为选非题，故正确答案为D。"},"from":{"file":"07-事业编职测/B类/2023/2023-05-07/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"政治常识","questionPages":[1],"answerPages":[2]},"idx":3,"pid":"p8da11424e5","sourceYears":[2023]},{"qid":"sy-c-20230507-001","no":1,"type":"政治常识","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"政治常识","tag":"未细分","confidence":"待复核","needsReview":true,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.unresolved","evidence":"（ ）。","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[1],"answer":[1]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20230507-001-题目-p01-116-214.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"打赢了人类历史上规模最大的脱贫攻坚战"},{"k":"B","t":"货物贸易总额和吸引外资均高居世界第一"},{"k":"C","t":"我国经济总量占世界经济的比重超过30%"},{"k":"D","t":"全国居民人均可支配收入历史性突破6 万元"}],"answer":"A","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20230507-001-解析-p01-103-356.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"党的二十大报告系统总结了十八大以来党和国家事业取得的历史性成就。对此，下列说法正确的是（ ）。","options":[{"k":"A","t":"打赢了人类历史上规模最大的脱贫攻坚战"},{"k":"B","t":"货物贸易总额和吸引外资均高居世界第一"},{"k":"C","t":"我国经济总量占世界经济的比重超过30%"},{"k":"D","t":"全国居民人均可支配收入历史性突破6 万元"}],"material":"","explanation":"1\n\n本题考查政治常识。\n\nA项正确，党的二十大报告指出，我们经过接续奋斗，实现了小康这个中华民族的千年梦想，我国发展站在了更高历史起点上。我们坚持精准扶贫、尽锐出战，打赢了人类历史上规模最大的脱贫攻坚战，全国八百三十二个贫困县全部摘帽，近一亿农村贫困人口实现脱贫，九百六十多万贫困人口实现易地搬迁，历史性地解决了绝对贫困问题，为全球减贫事业作出了重大贡献。\n\nB项错误，党的二十大报告指出，我国成为一百四十多个国家和地区的主要贸易伙伴，货物贸易总额居世界第一，吸引外资和对外投资居世界前列，形成更大范围、更宽领域、更深层次对外开放格局。故“吸引外资居世界第一”说法错误。\n\nC项错误，党的二十大报告指出，国内生产总值从五十四万亿元增长到一百一十四万亿元，我国经济总量占世界经济的比重达百分之十八点五，提高七点二个百分点，稳居世界第二位。故“我国经济总量占世界经济的比重超过30%”说法错误。\n\nD项错误，党的二十大报告指出，居民人均可支配收入从一万六千五百元增加到三万五千一百元。故“全国居民人均可支配收入历史性突破6万元”说法错误。\n\n故正确答案为A。"},"from":{"file":"07-事业编职测/C类/2023/2023-05-07/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"政治常识","questionPages":[1],"answerPages":[1]},"idx":0,"pid":"p45f7e1bcda","sourceYears":[2023]},{"qid":"sy-c-20230507-002","no":2,"type":"政治常识","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"政治常识","tag":"未细分","confidence":"待复核","needsReview":true,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.unresolved","evidence":"界观和方法论，坚持好、运用好贯穿其中的立场观点方法。对此，下列选项对应不准确的是（ ）。","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[1],"answer":[1]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20230507-002-题目-p01-210-324.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"推进改革发展往往牵一发而动全身——坚持系统观念"},{"k":"B","t":"中国的问题必须由中国人自己来解答——坚持自信自立"},{"k":"C","t":"回答并指导解决问题是理论的根本任务——坚持问题导向"},{"k":"D","t":"人民的创造性实践是理论创新的不竭源泉——坚持守正创新"}],"answer":"D","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20230507-002-解析-p01-352-590.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"党的二十大报告提出，继续推进实践基础上的理论创新，首先要把握好新时代中国特色社会主义思想的世界观和方法论，坚持好、运用好贯穿其中的立场观点方法。对此，下列选项对应不准确的是（ ）。","options":[{"k":"A","t":"推进改革发展往往牵一发而动全身——坚持系统观念"},{"k":"B","t":"中国的问题必须由中国人自己来解答——坚持自信自立"},{"k":"C","t":"回答并指导解决问题是理论的根本任务——坚持问题导向"},{"k":"D","t":"人民的创造性实践是理论创新的不竭源泉——坚持守正创新"}],"material":"","explanation":"本题考查政治常识。\n\nA项正确，党的二十大报告指出，必须坚持系统观念。万事万物是相互联系、相互依存的。只有用普遍联系的、全面系统的、发展变化的观点观察事物，才能把握事物发展规律。我国是一个发展中大国，仍处于社会主义初级阶段，正在经历广泛而深刻的社会变革，推进改革发展、调整利益关系往往牵一发而动全身。\n\nB项正确，党的二十大报告指出，必须坚持自信自立。中国人民和中华民族从近代以后的深重苦难走向伟大复兴的光明前景，从来就没有教科书，更没有现成答案。党的百年奋斗成功道路是党领导人民独立自主探索开辟出来的，马克思主义的中国篇章是中国共产党人依靠自身力量实践出来的，贯穿其中的一个基本点就是中国的问题必须从中国基本国情出发，由中国人自己来解答。\n\nC项正确，党的二十大报告指出，必须坚持问题导向。问题是时代的声音，回答并指导解决问题是理论的根本任务。今天我们所面临问题的复杂程度、解决问题的艰巨程度明显加大，给理论创新提出了全新要求。\n\nD项错误，党的二十大报告指出，必须坚持人民至上。人民性是马克思主义的本质属性，党的理论是来自人民、为了人民、造福人民的理论，人民的创造性实践是理论创新的不竭源泉。一切脱离人民的理论都是苍白无力的，一切不为人民造福的理论都是没有生命力的。故“人民的创造性实践是理论创新的不竭源泉一一坚持守正创新”说法错误。\n\n本题为选非题，故正确答案为D。"},"from":{"file":"07-事业编职测/C类/2023/2023-05-07/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"政治常识","questionPages":[1],"answerPages":[1]},"idx":1,"pid":"p45f7e1bcda","sourceYears":[2023]},{"qid":"sy-c-20230507-003","no":3,"type":"政治常识","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"政治常识","tag":"未细分","confidence":"待复核","needsReview":true,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.unresolved","evidence":"是（ ）。","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[1],"answer":[1,2]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20230507-003-题目-p01-319-433.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"组建金融监督管理总局，不再保留中国人民银行"},{"k":"B","t":"组建中央社会工作部，作为党中央议事协调机构"},{"k":"C","t":"组建国家数据局，由国家发展和改革委员会管理"},{"k":"D","t":"按照5%的比例精减中央和地方党政机关人员编制"}],"answer":"C","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20230507-003-解析-p01-586-812.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-c-20230507-003-解析-p02-51-232.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"2023 年3 月，中共中央、国务院印发了《党和国家机构改革方案》。关于该方案的内容，下列说法正确的是（ ）。","options":[{"k":"A","t":"组建金融监督管理总局，不再保留中国人民银行"},{"k":"B","t":"组建中央社会工作部，作为党中央议事协调机构"},{"k":"C","t":"组建国家数据局，由国家发展和改革委员会管理"},{"k":"D","t":"按照5%的比例精减中央和地方党政机关人员编制"}],"material":"","explanation":"3\n\n本题考查政治常识。\n\n2023年3月，中共中央、国务院印发了《党和国家机构改革方案》。\n\nA项错误，《党和国家机构改革方案》指出，组建国家金融监督管理总局。国家金融监督管理总局在中国银行保险监督管理委员会基础上组建，将中国人民银行对金融控股公司等金融集团的日常监管职责、有关金融消费者保护职责，中国证券监督管理委员会的投资者保护职责划入国家金融监督管理总局。不再保留中国银行保险监督管理委员会。故“不再保留中国人民银行”说法错误。\n\nB项错误，《党和国家机构改革方案》指出，组建中央社会工作部。负责统筹指导人民信访工作，指导人民建议征集工作，统筹推进党建引领基层治理和基层政权建设，统一领导全国性行业协会商会党的工作，协调推动行业协会商会深化改革和转型发展，指导混合所有制企业、非公有制企业和新经济组织、新社会组织、新就业群体党建工作，指导社会工作人才队伍建设等，作为党中央职能部门。故“作为党中央议事协调机构”说法错误。\n\nC项正确，《党和国家机构改革方案》指出，组建国家数据局。负责协调推进数据基础制度建设，统筹数据资源整合共享和开发利用，统筹推进数字中国、数字经济、数字社会规划和建设等，由国家发展和改革委员会管理。\n\nD项错误，《党和国家机构改革方案》指出，精减中央和国家机关人员编制。中央和国家机关各部门人员编制统一按照5%的比例进行精减，收回的编制主要用于加强重点领域和重要工作。中央垂管派出机构、驻外机构不纳入统一精减范围，根据行业和系统实际，盘活用好存量编制资源。故“按照5%的比例精减地方党政机关人员编制”说法错误。\n\n故正确答案为C。"},"from":{"file":"07-事业编职测/C类/2023/2023-05-07/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"政治常识","questionPages":[1],"answerPages":[1,2]},"idx":2,"pid":"p45f7e1bcda","sourceYears":[2023]},{"qid":"sy-c-20230507-004","no":4,"type":"政治常识","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"政治常识","tag":"未细分","confidence":"待复核","needsReview":true,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.unresolved","evidence":"错误的是（ ）。","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[1],"answer":[2]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20230507-004-题目-p01-428-542.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"城市管理网格员可以受理相关群众举报"},{"k":"B","t":"直播销售员属于互联网营销师的工种之一"},{"k":"C","t":"家庭教育指导师可策划家校协同育人活动"},{"k":"D","t":"电子数据取证分析师的工作不包括数据恢复"}],"answer":"D","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20230507-004-解析-p02-227-543.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"近年来，随着我国经济社会发展，人力资源社会保障部公布了一些“新职业”。下列关于新职业的说法，错误的是（ ）。","options":[{"k":"A","t":"城市管理网格员可以受理相关群众举报"},{"k":"B","t":"直播销售员属于互联网营销师的工种之一"},{"k":"C","t":"家庭教育指导师可策划家校协同育人活动"},{"k":"D","t":"电子数据取证分析师的工作不包括数据恢复"}],"material":"","explanation":"4\n\n本题考查政治常识。\n\nA项正确，城市管理网格员是运用现代城市网络化管理技术，巡查、核实、上报、处置市政工程（公用）设施、市容环境、社会管理事务等方面的问题，并对相关信息进行采集、分析、处置的人员。他们的工作任务包括操作信息采集设备，巡查、发现网格内市政工程（公用）设施、市容环境、社会管理事务等方面的问题，受理相关群众举报；操作系统平台对发现或群众举报的网格内市政工程（公用）设施、市容环境、社会管理事务等方面的问题进行核实、上报、记录；研究网格内市政工程（公用）设施、市容环境、社会管理事务等方面问题的立案事宜，提出处置方案；通知存在问题的责任单位，并协助解决相关问题；核实上级通报的问题，协助责任单位处置，并反馈处置结果；收集、整理、分析相关信息、数据，提出网格内城市治理优化建议。\n\nB项正确，互联网营销师有四大工种，即直播销售员、选品员、视频创推员、平台管理员。直播销售员是在直播过程中针对企业产品进行宣传推广，以及进行直接的直播营销人员；选品员是自产品选择、产品卖点提炼、商务谈判、直播流程设计中参与实施管理的人员；视频创推员是通过视频的创作及推广，为后续的直播销售充分预热和赋能，并进一步地开展用户互动工作的人员；平台管理员是针对直播平台进行后台管理，包括账号管理、数据监控，并通过分析指导进一步的直播销售过程的人员。\n\nC项正确，家庭教育指导师是指通过教育学、应用心理学、社会家庭学的理论知识，帮助家庭在夫妻关系、亲子关系、婆媳关系上建立良好的家庭环境，通过改变孩子的生活、学习习惯，建立孩子的德行和责任，帮助家庭幸福的专业人员。家庭教育指导师可以助力家校育人协同发展。\n\nD项错误，电子数据取证分析师是从事电子数据的收集提取、数据恢复及取证分析的人员。电子数据取证分析师的工作包括数据恢复。\n\n本题为选非题，故正确答案为D。"},"from":{"file":"07-事业编职测/C类/2023/2023-05-07/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"政治常识","questionPages":[1],"answerPages":[2]},"idx":3,"pid":"p45f7e1bcda","sourceYears":[2023]},{"qid":"sy-a-20230826-001","no":1,"type":"政治常识","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"政治常识","tag":"未细分","confidence":"待复核","needsReview":true,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.unresolved","evidence":"治领悟力、政治执行力","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[1],"answer":[1]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-a-20230826-001-题目-p01-116-308.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"①②③"},{"k":"B","t":"①②④"},{"k":"C","t":"①③④"},{"k":"D","t":"②③④"}],"answer":"A","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-a-20230826-001-解析-p01-105-436.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"2023 年第3 期《求是》杂志发表了习近平总书记的重要文章《全面从严治党探索出依靠党的自我革命跳出历史周期率的成功路径》，文章中提及的内容包括（ ）。\n\n①党中央把全面从严治党纳入“四个全面”战略布局\n\n②勇于自我革命和接受人民监督是内在一致的，都源于党的初心使命\n\n③腐败是最容易颠覆政权的问题，反腐败是最彻底的自我革命\n\n④要全面贯彻落实党的二十大精神，坚持党对政法工作的绝对领导，提高政治站位和政治判断力，政治领悟力、政治执行力","options":[{"k":"A","t":"①②③"},{"k":"B","t":"①②④"},{"k":"C","t":"①③④"},{"k":"D","t":"②③④"}],"material":"","explanation":"1\n\n本题考查政治常识。\n\n①正确，《全面从严治党探索出依靠党的自我革命跳出历史周期率的成功路径》文章指出，今年是党的十八大以来第十个年头，十年磨一剑，党中央把全面从严治党纳入“四个全面”战略布局，以前所未有的勇气和定力推进党风廉政建设和反腐败斗争，刹住了一些多年未刹住的歪风邪气，解决了许多长期没有解决的顽瘴瘤疾，清除了党、国家、军队内部存在的严重隐患，管党治党宽松软状况得到根本扭转。\n\n②正确，《全面从严治党探索出依靠党的自我革命跳出历史周期率的成功路径》文章指出，勇于自我革命和接受人民监督是内在一致的，都源于党的初心使命。一百年来，党外靠发展人民民主、接受人民监督，内靠全面从严治党、推进自我革命，勇于坚持真理、修正错误，勇于刀刃向内、刮骨疗毒，保证了党长盛不衰、不断发展壮大。\n\n③正确，《全面从严治党探索出依靠党的自我革命跳出历史周期率的成功路径》文章指出，坚持以雷霆之势反腐惩恶，打好自我革命攻坚战、持久战。古人说：“国家之败，由官邪也。”腐败是最容易颠覆政权的问题，反腐败是最彻底的自我革命。\n\n④错误，2023年1月，中共中央总书记、国家主席、中央军委主席习近平对政法工作作出重要指示强调，政法工作是党和国家工作的重要组成部分。要全面贯彻落实党的二十大精神，坚持党对政法工作的绝对领导，提高政治站位和政治判断力、政治领悟力、政治执行力，坚持以人民为中心，坚持中国特色社会主义法治道路，坚持改革创新，坚持发扬斗争精神，奋力推进政法工作现代化，全力履行维护国家政治安全、确保社会大局稳定、促进社会公平正义、保障人民安居乐业的职责使命，为全面建设社会主义现代化国家、全面推进中华民族伟大复兴贡献力量。④内容不属于全面从严治党探索出依靠党的自我革命跳出历史周期率的成功路径》文章提及的内容。\n\n故正确答案为 A。"},"from":{"file":"07-事业编职测/A类/2023/2023-08-26/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"政治常识","questionPages":[1],"answerPages":[1]},"idx":0,"pid":"pdb4d1b42cf","sourceYears":[2023]},{"qid":"sy-a-20230826-002","no":2,"type":"政治常识","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"政治常识","tag":"未细分","confidence":"待复核","needsReview":true,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.unresolved","evidence":"④没有法律法规依据不得在政务服务前要求企业自行检测","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[1],"answer":[1]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-a-20230826-002-题目-p01-304-495.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"①③"},{"k":"B","t":"①④"},{"k":"C","t":"②③"},{"k":"D","t":"②④"}],"answer":"B","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-a-20230826-002-解析-p01-432-702.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"2023 年7 月，《中共中央 国务院关于促进民营经济发展壮大的意见》发布。该文件提出，要构建高水平社会主义市场经济体制，持续优化稳定公平透明可预期的发展环境，充分激发民营经济生机活力。下列选项中，体现“持续优化民营经济发展环境”的是（ ）。\n\n①优化个体工商户转企业相关政策，降低转换成本\n\n②鼓励民营企业拓展海外业务，有序参与境外项目\n\n③支持引导民营企业规范股东行为、强化内部监督\n\n④没有法律法规依据不得在政务服务前要求企业自行检测","options":[{"k":"A","t":"①③"},{"k":"B","t":"①④"},{"k":"C","t":"②③"},{"k":"D","t":"②④"}],"material":"","explanation":"2\n\n本题考查政治常识。\n\n《中共中央国务院关于促进民营经济发展壮大的意见》（以下简称《意见》）中指出要“持续优化民营经济发展环境”，有下列举措：（一）持续破除市场准入壁垒。（二）全面落实公平竞争政策制度。\n\n（三）完善社会信用激励约束机制。（四）完善市场化重整机制。\n\n①正确，《意见》指出：“完善市场化重整机制。鼓励民营企业盘活存量资产回收资金。坚持精准识别、分类施策，对陷入财务困境但仍具有发展前景和挽救价值的企业，按照市场化、法治化原则，积极适用破产重整、破产和解程序。推动修订企业破产法并完善配套制度。优化个体工商户转企业相关政策，降低转换成本。”\n\n②③错误，“鼓励民营企业拓展海外业务”、“支持引导民营企业完善法人治理结构、规范股东行为、强化内部监督”，体现的是着力推动民营经济实现高质量发展，而不是持续优化民营经济发展环境。\n\n④正确，《意见》指出：“持续破除市场准入壁垒。各地区各部门不得以备案、注册、年检、认定、认证、指定、要求设立分公司等形式设定或变相设定准入障碍。清理规范行政审批、许可、备案等政务服务事项的前置条件和审批标准，不得将政务服务事项转为中介服务事项，没有法律法规依据不得在政务服务前要求企业自行检测、检验、认证、鉴定、公证或提供证明等。稳步开展市场准入效能评估，建立市场准入壁垒投诉和处理回应机制，完善典型案例归集和通报制度。”\n\n故正确答案为B。"},"from":{"file":"07-事业编职测/A类/2023/2023-08-26/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"政治常识","questionPages":[1],"answerPages":[1]},"idx":1,"pid":"pdb4d1b42cf","sourceYears":[2023]},{"qid":"sy-a-20230826-003","no":3,"type":"政治常识","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"政治常识","tag":"未细分","confidence":"待复核","needsReview":true,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.unresolved","evidence":"下列关于该意见的说法，错误的是（ ）。","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[1],"answer":[1,2]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-a-20230826-003-题目-p01-491-604.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"发展壮大医疗卫生队伍，把工作重点放在农村和社区"},{"k":"B","t":"公立医疗机构设立公共卫生科等直接从事疾病预防控制工作的科室"},{"k":"C","t":"落实执业医师服务基层制度，鼓励医师到医疗资源稀缺地区多点执业"},{"k":"D","t":"深化卫生专业技术人员职称制度改革，把医学技能放在人才评价首位"}],"answer":"D","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-a-20230826-003-解析-p01-697-812.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-a-20230826-003-解析-p02-51-264.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"2023 年3 月23 日，中共中央办公厅、国务院办公厅印发了《关于进一步完善医疗卫生服务体系的意见》。\n\n下列关于该意见的说法，错误的是（ ）。","options":[{"k":"A","t":"发展壮大医疗卫生队伍，把工作重点放在农村和社区"},{"k":"B","t":"公立医疗机构设立公共卫生科等直接从事疾病预防控制工作的科室"},{"k":"C","t":"落实执业医师服务基层制度，鼓励医师到医疗资源稀缺地区多点执业"},{"k":"D","t":"深化卫生专业技术人员职称制度改革，把医学技能放在人才评价首位"}],"material":"","explanation":"3\n\n本题考查政治常识。\n\n2023年3月23日，中共中央办公厅、国务院办公厅印发了《关于进一步完善医疗卫生服务体系的意见》。\n\nA项正确，《关于进一步完善医疗卫生服务体系的意见》指出，提升卫生健康人才能力。发展壮大医疗卫生队伍，把工作重点放在农村和社区。加大基层、边远地区和紧缺专业人才培养扶持力度，缩小城乡、地区、专业之间人才配置差距。\n\nB项正确，《关于进一步完善医疗卫生服务体系的意见》指出，加强防治结合。创新医防协同、医防融合机制。公立医疗机构设立公共卫生科等直接从事疾病预防控制工作的科室。全面推进医疗机构和专业公共卫生机构的深度协作，建立人才流动、交叉培训、服务融合、信息共享等机制。\n\nC项正确，《关于进一步完善医疗卫生服务体系的意见》指出，推进农村卫生人才定向培养，落实执业医师服务基层制度，鼓励医师到基层、边远地区、医疗资源稀缺地区和其他有需求的医疗机构多点执业。\n\n激励乡村医生参加学历教育、考取执业（助理）医师资格，推进助理全科医生培训。\n\nD项错误，《关于进一步完善医疗卫生服务体系的意见》指出，深化卫生专业技术人员职称制度改革，以品德能力业绩为导向，科学设置评价标准，把医德医风放在人才评价首位。\n\n本题为选非题，故正确答案为D。"},"from":{"file":"07-事业编职测/A类/2023/2023-08-26/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"政治常识","questionPages":[1],"answerPages":[1,2]},"idx":2,"pid":"pdb4d1b42cf","sourceYears":[2023]},{"qid":"sy-b-20230826-001","no":1,"type":"政治常识","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"政治常识","tag":"未细分","confidence":"待复核","needsReview":true,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.unresolved","evidence":"治领悟力、政治执行力","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[1],"answer":[1]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-b-20230826-001-题目-p01-116-308.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"①②③"},{"k":"B","t":"①②④"},{"k":"C","t":"①③④"},{"k":"D","t":"②③④"}],"answer":"A","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-b-20230826-001-解析-p01-102-434.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"2023 年第3 期《求是》杂志发表了习近平总书记的重要文章《全面从严治党探索出依靠党的自我革命跳出历史周期率的成功路径》，文章中提及的内容包括（ ）。\n\n①党中央把全面从严治党纳入“四个全面”战略布局\n\n②勇于自我革命和接受人民监督是内在一致的，都源于党的初心使命\n\n③腐败是最容易颠覆政权的问题，反腐败是最彻底的自我革命\n\n④要全面贯彻落实党的二十大精神，坚持党对政法工作的绝对领导，提高政治站位和政治判断力，政治领悟力、政治执行力","options":[{"k":"A","t":"①②③"},{"k":"B","t":"①②④"},{"k":"C","t":"①③④"},{"k":"D","t":"②③④"}],"material":"","explanation":"1\n\n本题考查政治常识。\n\n①正确，《全面从严治党探索出依靠党的自我革命跳出历史周期率的成功路径》文章指出，今年是党的十八大以来第十个年头，十年磨一剑，党中央把全面从严治党纳入“四个全面”战略布局，以前所未有的勇气和定力推进党风廉政建设和反腐败斗争，刹住了一些多年未刹住的歪风邪气，解决了许多长期没有解决的顽瘴瘤疾，清除了党、国家、军队内部存在的严重隐患，管党治党宽松软状况得到根本扭转。\n\n②正确，《全面从严治党探索出依靠党的自我革命跳出历史周期率的成功路径》文章指出，勇于自我革命和接受人民监督是内在一致的，都源于党的初心使命。一百年来，党外靠发展人民民主、接受人民监督，内靠全面从严治党、推进自我革命，勇于坚持真理、修正错误，勇于刀刃向内、刮骨疗毒，保证了党长盛不衰、不断发展壮大。\n\n③正确，《全面从严治党探索出依靠党的自我革命跳出历史周期率的成功路径》文章指出，坚持以雷霆之势反腐惩恶，打好自我革命攻坚战、持久战。古人说：“国家之败，由官邪也。”腐败是最容易颠覆政权的问题，反腐败是最彻底的自我革命。\n\n④错误，2023年1月，中共中央总书记、国家主席、中央军委主席习近平对政法工作作出重要指示强调，政法工作是党和国家工作的重要组成部分。要全面贯彻落实党的二十大精神，坚持党对政法工作的绝对领导，提高政治站位和政治判断力、政治领悟力、政治执行力，坚持以人民为中心，坚持中国特色社会主义法治道路，坚持改革创新，坚持发扬斗争精神，奋力推进政法工作现代化，全力履行维护国家政治安全、确保社会大局稳定、促进社会公平正义、保障人民安居乐业的职责使命，为全面建设社会主义现代化国家、全面推进中华民族伟大复兴贡献力量。④内容不属于全面从严治党探索出依靠党的自我革命跳出历史周期率的成功路径》文章提及的内容。\n\n故正确答案为 A。"},"from":{"file":"07-事业编职测/B类/2023/2023-08-26/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"政治常识","questionPages":[1],"answerPages":[1]},"idx":0,"pid":"pe01a49fcf5","sourceYears":[2023]},{"qid":"sy-b-20230826-003","no":3,"type":"政治常识","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"政治常识","tag":"未细分","confidence":"待复核","needsReview":true,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.unresolved","evidence":"④国际收支保持平衡，人民币汇率波动较大","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[1],"answer":[1,2]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-b-20230826-003-题目-p01-397-573.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"①②③"},{"k":"B","t":"①②④"},{"k":"C","t":"①③④"},{"k":"D","t":"②③④"}],"answer":"A","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-b-20230826-003-解析-p01-617-812.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-b-20230826-003-解析-p02-51-91.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"2023 年3 月5 日，十四届全国人大一次会议上的《政府工作报告》对过去一年的工作进行了回顾，下列说法与报告内容相符的是（ ）。\n\n①我国经济发展遇到疫情等国内外多重超预期因素冲击\n\n②高效统筹疫情防控和经济社会发展\n\n③中央财政收支符合预算、支出略有结余\n\n④国际收支保持平衡，人民币汇率波动较大","options":[{"k":"A","t":"①②③"},{"k":"B","t":"①②④"},{"k":"C","t":"①③④"},{"k":"D","t":"②③④"}],"material":"","explanation":"3\n\n本题考查政治常识。\n\n①②正确，2023年《政府工作报告》指出，过去一年，我国经济发展遇到疫情等国内外多重超预期因素冲击。在党中央坚强领导下，我们高效统筹疫情防控和经济社会发展，根据病毒变化和防疫形势，优化调整疫情防控措施。\n\n③正确、④错误，2023年《政府工作报告》指出，全年国内生产总值增长3%，城镇新增就业1206万人，年末城镇调查失业率降到5.5%，居民消费价格上涨2%。货物进出口总额增长7.7%。财政赤字率控制在2.8%，中央财政收支符合预算、支出略有结余。国际收支保持平衡，人民币汇率在全球主要货币中表现相对稳健。\n\n故正确答案为A。"},"from":{"file":"07-事业编职测/B类/2023/2023-08-26/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"政治常识","questionPages":[1],"answerPages":[1,2]},"idx":2,"pid":"pe01a49fcf5","sourceYears":[2023]},{"qid":"sy-b-20230826-004","no":4,"type":"政治常识","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"政治常识","tag":"未细分","confidence":"待复核","needsReview":true,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.unresolved","evidence":"关于新中国成立以来的经济发展情况，下列说法错误的是（ ）。","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[1],"answer":[2]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-b-20230826-004-题目-p01-569-667.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"我国已拥有联合国产业分类中所列全部工业门类"},{"k":"B","t":"2006 年1 月1 日起，我国全面取消农业税，农业税已成为历史"},{"k":"C","t":"中国第一批国产汽车——“解放牌”载重汽车在长春试制成功"},{"k":"D","t":"党的十一届三中全会后，我国从优先发展轻工业转向优先发展重工业"}],"answer":"D","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-b-20230826-004-解析-p02-86-262.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"关于新中国成立以来的经济发展情况，下列说法错误的是（ ）。","options":[{"k":"A","t":"我国已拥有联合国产业分类中所列全部工业门类"},{"k":"B","t":"2006 年1 月1 日起，我国全面取消农业税，农业税已成为历史"},{"k":"C","t":"中国第一批国产汽车——“解放牌”载重汽车在长春试制成功"},{"k":"D","t":"党的十一届三中全会后，我国从优先发展轻工业转向优先发展重工业"}],"material":"","explanation":"4\n\n本题考查政治常识。\n\nA项正确，中国目前是全球唯一拥有联合国产业分类中所有工业门类的国家，包括了39个工业大类，191个中类，525个小类。\n\nB项正确，2005年12月29日，十届全国人大常委会第十九次会议决定，自2006年1月1日起，废止《中华人民共和国农业税条例》，全面取消农业税，中国的农业税从此退出历史舞台。\n\nC项正确，1956年7月13日，长春第一汽车制造厂试制成功第一批国产“解放”牌载重汽车。\n\nD项错误，1978年十一届三中全会后，中国开始了一系列经济改革，进一步推进对外开放。有了前 20年所打下的国家工业化的良好基础，中国开始进行工业化战略内的结构调整，从优先发展重化工业转向优先发展轻工业。\n\n本题为选非题，故正确答案为D。"},"from":{"file":"07-事业编职测/B类/2023/2023-08-26/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"政治常识","questionPages":[1],"answerPages":[2]},"idx":3,"pid":"pe01a49fcf5","sourceYears":[2023]},{"qid":"sy-c-20230826-001","no":1,"type":"政治常识","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"政治常识","tag":"未细分","confidence":"待复核","needsReview":true,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.unresolved","evidence":"④没有法律法规依据不得在政务服务前要求企业自行检测","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[1],"answer":[1]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20230826-001-题目-p01-189-337.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"①③"},{"k":"B","t":"①④"},{"k":"C","t":"②③"},{"k":"D","t":"②④"}],"answer":"B","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20230826-001-解析-p01-104-414.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"2023 年7 月，《中共中央国务院关于促进民营经济发展壮大的意见》发布。该文件提出，要构建高水平社会主义市场经济体制，持续优化稳定公平透明可预期的发展环境，充分激发民营经济生机活力。下列选项中，体现“持续优化民营经济发展环境”的是（ ）。\n\n①优化个体工商户转企业相关政策，降低转换成本\n\n②鼓励民营企业拓展海外业务，有序参与境外项目\n\n③支持引导民营企业规范股东行为、强化内部监督\n\n④没有法律法规依据不得在政务服务前要求企业自行检测","options":[{"k":"A","t":"①③"},{"k":"B","t":"①④"},{"k":"C","t":"②③"},{"k":"D","t":"②④"}],"material":"","explanation":"1、参考答案：B\n\n解析：本题考查政治常识。\n\n《中共中央国务院关于促进民营经济发展壮大的意见》（以下简称《意见》）中指出要“持续优化民营经济发展环境”，有下列举措：（一）持续破除市场准入壁垒。（二）全面落实公平竞争政策制度。（三）完善社会信用激励约束机制。（四）完善市场化重整机制。\n\n①正确，《意见》指出：“完善市场化重整机制。鼓励民营企业盘活存量资产回收资金。坚持精准识别、分类施策，对陷入财务困境但仍具有发展前景和挽救价值的企业，按照市场化、法治化原则，积极适用破产重整、破产和解程序。推动修订企业破产法并完善配套制度。优化个体工商户转企业相关政策，降低转换成本。”\n\n②③错误，“鼓励民营企业拓展海外业务”、“支持引导民营企业完善法人治理结构、规范股东行为、强化内部监督”，体现的是着力推动民营经济实现高质量发展，而不是持续优化民营经济发展环境。\n\n④正确，《意见》指出：“持续破除市场准入壁垒。各地区各部门不得以备案、注册、年检、认定、认证、指定、要求设立分公司等形式设定或变相设定准入障碍。清理规范行政审批、许可、备案等政务服务事项的前置条件和审批标准，不得将政务服务事项转为中介服务事项，没有法律法规依据不得在政务服务前要求企业自行检测、检验、认证、鉴定、公证或提供证明等。稳步开展市场准入效能评估，建立市场准入壁垒投诉和处理回应机制，完善典型案例归集和通报制度。”\n\n故正确答案为B。"},"from":{"file":"07-事业编职测/C类/2023/2023-08-26/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"政治常识","questionPages":[1],"answerPages":[1]},"idx":0,"pid":"p02398bdfac","sourceYears":[2023]},{"qid":"sy-c-20230826-002","no":2,"type":"政治常识","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"政治常识","tag":"未细分","confidence":"待复核","needsReview":true,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.unresolved","evidence":"④国际收支保持平衡，人民币汇率波动较大","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[1],"answer":[1]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20230826-002-题目-p01-333-463.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"①②③"},{"k":"B","t":"①②④"},{"k":"C","t":"①③④"},{"k":"D","t":"②③④"}],"answer":"A","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20230826-002-解析-p01-410-594.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"2023 年3 月5 日，十四届全国人大一次会议上的《政府工作报告》对过去一年的工作进行了回顾，下列说法与报告内容相符的是（ ）。\n\n①我国经济发展遇到疫情等国内外多重超预期因素冲击\n\n②高效统筹疫情防控和经济社会发展\n\n③中央财政收支符合预算、支出略有结余\n\n④国际收支保持平衡，人民币汇率波动较大","options":[{"k":"A","t":"①②③"},{"k":"B","t":"①②④"},{"k":"C","t":"①③④"},{"k":"D","t":"②③④"}],"material":"","explanation":"2、参考答案：A\n\n解析：本题考查政治常识。\n\n①②正确，2023 年《政府工作报告》指出，过去一年，我国经济发展遇到疫情等国内外多重超预期因素冲击。在党中央坚强领导下，我们高效统筹疫情防控和经济社会发展，根据病毒变化和防疫形势，优化调整疫情防控措施。\n\n③正确、④错误，2023 年《政府工作报告》指出，全年国内生产总值增长3%，城镇新增就业1206 万人，年末城镇调查失业率降到5.5%，居民消费价格上涨2%。货物进出口总额增长7.7%。财政赤字率控制在2.8%，中央财政收支符合预算、支出略有结余。国际收支保持平衡，人民币汇率在全球主要货币中表现相对稳健。\n\n故正确答案为A。"},"from":{"file":"07-事业编职测/C类/2023/2023-08-26/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"政治常识","questionPages":[1],"answerPages":[1]},"idx":1,"pid":"p02398bdfac","sourceYears":[2023]},{"qid":"sy-c-20230826-006","no":6,"type":"政治常识","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"政治常识","tag":"未细分","confidence":"待复核","needsReview":true,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.unresolved","evidence":"关于新中国成立以来的经济发展情况，下列说法错误的是（ ）。","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[1,2],"answer":[3]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20230826-006-题目-p01-747-812.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-c-20230826-006-题目-p02-51-149.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"我国已拥有联合国产业分类中所列全部工业门类"},{"k":"B","t":"2006 年1 月1 日起，我国全面取消农业税，农业税已成为历史"},{"k":"C","t":"中国第一批国产汽车——“解放牌”载重汽车在长春试制成功"},{"k":"D","t":"党的十一届三中全会后，我国从优先发展轻工业转向优先发展重工业"}],"answer":"D","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20230826-006-解析-p03-162-365.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"关于新中国成立以来的经济发展情况，下列说法错误的是（ ）。","options":[{"k":"A","t":"我国已拥有联合国产业分类中所列全部工业门类"},{"k":"B","t":"2006 年1 月1 日起，我国全面取消农业税，农业税已成为历史"},{"k":"C","t":"中国第一批国产汽车——“解放牌”载重汽车在长春试制成功"},{"k":"D","t":"党的十一届三中全会后，我国从优先发展轻工业转向优先发展重工业"}],"material":"","explanation":"6、参考答案：D\n\n解析：本题考查政治常识。\n\nA 项正确，中国目前是全球唯一拥有联合国产业分类中所有工业门类的国家，包括了39 个工业大类，191 个中类，525 个小类。\n\nB 项正确，2005 年12 月29 日，十届全国人大常委会第十九次会议决定，自2006 年1 月1 日起，废止《中华人民共和国农业税条例》，全面取消农业税，中国的农业税从此退出历史舞台。\n\nC 项正确，1956 年7 月13 日，长春第一汽车制造厂试制成功第一批国产“解放”牌载重汽车。\n\nD 项错误，1978 年十一届三中全会后，中国开始了一系列经济改革，进一步推进对外开放。有了前20年所打下的国家工业化的良好基础，中国开始进行工业化战略内的结构调整，从优先发展重化工业转向优先发展轻工业。\n\n本题为选非题，故正确答案为D。"},"from":{"file":"07-事业编职测/C类/2023/2023-08-26/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"政治常识","questionPages":[1,2],"answerPages":[3]},"idx":5,"pid":"p02398bdfac","sourceYears":[2023]},{"qid":"sy-a-20220521-001","no":1,"type":"政治常识","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"政治常识","tag":"未细分","confidence":"待复核","needsReview":true,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.unresolved","evidence":"斗目标新征程，朝着实现中华民族伟大复兴的宏伟目标继续前进","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[1],"answer":[1]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-a-20220521-001-题目-p01-116-386.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"1 项"},{"k":"B","t":"2 项"},{"k":"C","t":"3 项"},{"k":"D","t":"4 项"}],"answer":"D","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-a-20220521-001-解析-p01-105-358.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"党的十九届六中全会审议通过了一份特别的“百年总结”——《中共中央关于党的百年奋斗重大成就和历史经验的决议》。在这份决议中，提到了党在各个历史时期的主要任务。对此，下列说法正确的有几项？\n\n（ ）\n\n①新民主主义革命时期，党面临的主要任务是，反对帝国主义、封建主义、官僚资本主义，争取民族独立、人民解放，为实现中华民族伟大复兴创造根本社会条件\n\n②社会主义革命和建设时期，党面临的主要任务是，实现从新民主主义到社会主义的转变，进行社会主义革命，推进社会主义建设，为实现中华民族伟大复兴奠定根本政治前提和制度基础\n\n③改革开放和社会主义现代化建设新时期，党面临的主要任务是，继续探索中国建设社会主义的正确道路，解放和发展社会生产力，使人民摆脱贫困、尽快富裕起来，为实现中华民族伟大复兴提供充满新的活力的体制保证和快速发展的物质条件\n\n④中国特色社会主义进入新时代，党面临的主要任务是，实现第一个百年奋斗目标开启实现第二个百年奋斗目标新征程，朝着实现中华民族伟大复兴的宏伟目标继续前进","options":[{"k":"A","t":"1 项"},{"k":"B","t":"2 项"},{"k":"C","t":"3 项"},{"k":"D","t":"4 项"}],"material":"","explanation":"1\n\n本题考查政治常识。\n\n十九届六中全会于2021年11月8日至11日在北京召开，并审议通过了《中共中央关于党的百年奋斗重大成就和历史经验的决议》。\n\n①项正确，全会提出，新民主主义革命时期，党面临的主要任务是，反对帝国主义、封建主义、官僚资本主义，争取民族独立、人民解放，为实现中华民族伟大复兴创造根本社会条件。\n\n②项正确，全会提出，社会主义革命和建设时期，党面临的主要任务是，实现从新民主主义到社会主义的转变，进行社会主义革命，推进社会主义建设，为实现中华民族伟大复兴奠定根本政治前提和制度基础。\n\n③项正确，全会提出，改革开放和社会主义现代化建设新时期，党面临的主要任务是，继续探索中国建设社会主义的正确道路，解放和发展社会生产力，使人民摆脱贫困、尽快富裕起来，为实现中华民族伟大复兴提供充满新的活力的体制保证和快速发展的物质条件。\n\n④项正确，全会提出，党的十八大以来，中国特色社会主义进入新时代。党面临的主要任务是，实现第一个百年奋斗目标，开启实现第二个百年奋斗目标新征程，朝着实现中华民族伟大复兴的宏伟目标继续前进。党领导人民自信自强、守正创新，创造了新时代中国特色社会主义的伟大成就。\n\n故正确答案为D。"},"from":{"file":"07-事业编职测/A类/2022/2022-05-21/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"政治常识","questionPages":[1],"answerPages":[1]},"idx":0,"pid":"pc4596e3c56","sourceYears":[2022]},{"qid":"sy-a-20220521-002","no":2,"type":"政治常识","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"政治常识","tag":"未细分","confidence":"待复核","needsReview":true,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.unresolved","evidence":"④引导金融机构加大对实体经济特别是小微企业、科技创新、绿色发展的支持","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[1],"answer":[1]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-a-20220521-002-题目-p01-382-558.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"①②③"},{"k":"B","t":"①②④"},{"k":"C","t":"①③④"},{"k":"D","t":"②③④"}],"answer":"B","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-a-20220521-002-解析-p01-353-560.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"2021 年12 月8 日至10 日，中央经济工作会议在北京举行。下列选项中，符合会议所提出的宏观政策要求的是（ ）。\n\n①坚决遏制新增地方政府隐性债务\n\n②实施新的减税降费政策，适度超前开展基础设施投资\n\n③强化知识产权保护，营造国有制企业竞相发展的良好环境\n\n④引导金融机构加大对实体经济特别是小微企业、科技创新、绿色发展的支持","options":[{"k":"A","t":"①②③"},{"k":"B","t":"①②④"},{"k":"C","t":"①③④"},{"k":"D","t":"②③④"}],"material":"","explanation":"本题考查政治常识。\n\n2021年中央经济工作会议于2021年12月8日至10日在北京举行，会议要求如下：\n\n①项、②项、④项正确，一是宏观政策要稳健有效。要继续实施积极的财政政策和稳健的货币政策。积极的财政政策要提升效能，更加注重精准、可持续。要保证财政支出强度，加快支出进度。实施新的减税降费政策，强化对中小微企业、个体工商户、制造业、风险化解等的支持力度，适度超前开展基础设施投资。党政机关要坚持过紧日子。严肃财经纪律。坚决遇制新增地方政府隐性债务。稳健的货币政策要灵活适度，保持流动性合理充裕。引导金融机构加大对实体经济特别是小微企业、科技创新、绿色发展的支持。财政政策和货币政策要协调联动，跨周期和逆周期宏观调控政策要有机结合。实施好扩大内需战略，增强发展内生动力。\n\n③项错误，二是微观政策要持续激发市场主体活力。要提高市场主体信心，深入推进公平竞争政策实施加强反垄断和反不正当竞争，以公正监管保障公平竞争。强化知识产权保护，营造各类所有制企业竞相发展的良好环境。强化契约精神，有效治理恶意拖欠账款和逃废债行为。\n\n故正确答案为B。"},"from":{"file":"07-事业编职测/A类/2022/2022-05-21/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"政治常识","questionPages":[1],"answerPages":[1]},"idx":1,"pid":"pc4596e3c56","sourceYears":[2022]},{"qid":"sy-a-20220521-003","no":3,"type":"政治常识","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"政治常识","tag":"未细分","confidence":"待复核","needsReview":true,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.unresolved","evidence":"①胸怀大局②自信开放③为国争光④迎难而上⑤追求卓越⑥共创未来⑦人民至上","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[1],"answer":[1]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-a-20220521-003-题目-p01-553-698.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"①②④⑤⑥"},{"k":"B","t":"①③④⑤⑦"},{"k":"C","t":"②③④⑥⑦"},{"k":"D","t":"②③⑤⑥⑦"}],"answer":"A","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-a-20220521-003-解析-p01-556-654.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"2022 年4 月8 日上午，北京冬奥会、冬残奥会总结表彰大会在人民大会堂隆重举行。中共中央总书记、国家主席、中央军委主席习近平出席大会并发表重要讲话阐述了北京冬奥精神。下列属于北京冬奥精神的是（ ）。\n\n①胸怀大局②自信开放③为国争光④迎难而上⑤追求卓越⑥共创未来⑦人民至上","options":[{"k":"A","t":"①②④⑤⑥"},{"k":"B","t":"①③④⑤⑦"},{"k":"C","t":"②③④⑥⑦"},{"k":"D","t":"②③⑤⑥⑦"}],"material":"","explanation":"本题考查政治常识。\n\n2022年4月8日上午，北京冬奥会、冬残奥会总结表彰大会在人民大会堂隆重举行。中共中央总书记、国家主席、中央军委主席习近平出席大会并发表重要讲话。习总书记指出，北京冬奥会、冬残奥会广大参与者珍惜伟大时代赋予的机遇，在冬奥申办、筹办、举办的过程中，共同创造了北京冬奥精神。这个精神是：胸怀大局、自信开放、迎难而上、追求卓越、共创未来。\n\n故正确答案为A。"},"from":{"file":"07-事业编职测/A类/2022/2022-05-21/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"政治常识","questionPages":[1],"answerPages":[1]},"idx":2,"pid":"pc4596e3c56","sourceYears":[2022]},{"qid":"sy-a-20220521-006","no":6,"type":"政治常识","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"政治常识","tag":"未细分","confidence":"待复核","needsReview":true,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.unresolved","evidence":"关于习近平总书记对健康中国的重要论述，下列说法不准确的是（ ）。","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[2],"answer":[2]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-a-20220521-006-题目-p02-272-370.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"人民健康是人民幸福生活的基础"},{"k":"B","t":"预防是最经济最有效的健康策略"},{"k":"C","t":"中医是人类同疾病斗争的锐利武器"},{"k":"D","t":"把健康融入所有政策，人民共建共享"}],"answer":"C","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-a-20220521-006-解析-p02-432-670.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"关于习近平总书记对健康中国的重要论述，下列说法不准确的是（ ）。","options":[{"k":"A","t":"人民健康是人民幸福生活的基础"},{"k":"B","t":"预防是最经济最有效的健康策略"},{"k":"C","t":"中医是人类同疾病斗争的锐利武器"},{"k":"D","t":"把健康融入所有政策，人民共建共享"}],"material":"","explanation":"本题考查政治常识。\n\nA项正确，2021年3月23日，习近平总书记在福建考察时指出；“现代化最重要的指标还是人民健康，这是人民幸福生活的基础。把这件事抓牢，人民至上、生命至上应该是全党全社会必须牢牢树立的一个理念。”\n\nB项正确，2021年3月6日，习近平总书记看望参加全国政协十三届四次会议的医药卫生界、教育界委员时指出：人民健康是社会文明进步的基础，是民族昌盛和国家富强的重要标志。这次抗击新冠肺炎疫情的实践再次证明，预防是最经济最有效的健康策略。\n\nC项错误，2020年6月2日，习近平总书记主持召开专家学者座谈会时指出；中西医结合、中西药并用，是这次疫情防控的一大特点，也是中医药传承精华、守正创新的生动实践。要加强对中医药工作的组织领导，推动中西医药相互补充、协调发展。\n\nD项正确，2016年8月19日，习近平总书记在全国卫生与健康大会上指出：“新形势下，我国卫生与健康工作方针是：以基层为重点，以改革创新为动力，预防为主，中西医并重，把健康融入所有政策，人民共建共享。”“这个方针的根本点是坚持以人民为中心的发展思想，坚持为人民健康服务，这是我国卫生与健康事业必须一以贯之坚持的基本要求。”\n\n本题为选非题，故正确答案为C。"},"from":{"file":"07-事业编职测/A类/2022/2022-05-21/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"政治常识","questionPages":[2],"answerPages":[2]},"idx":5,"pid":"pc4596e3c56","sourceYears":[2022]},{"qid":"sy-b-20220521-001","no":1,"type":"政治常识","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"政治常识","tag":"未细分","confidence":"待复核","needsReview":true,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.unresolved","evidence":"斗目标新征程，朝着实现中华民族伟大复兴的宏伟目标继续前进","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[1],"answer":[1]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-b-20220521-001-题目-p01-116-370.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"1 项"},{"k":"B","t":"2 项"},{"k":"C","t":"3 项"},{"k":"D","t":"4 项"}],"answer":"D","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-b-20220521-001-解析-p01-105-358.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"党的十九届六中全会审议通过了一份特别的“百年总结”——《中共中央关于党的百年奋斗重大成就和历史经验的决议》。在这份决议中，提到了党在各个历史时期的主要任务。对此，下列说法正确的有几项？（ ）\n\n①新民主主义革命时期，党面临的主要任务是，反对帝国主义、封建主义、官僚资本主义，争取民族独立、人民解放，为实现中华民族伟大复兴创造根本社会条件\n\n②社会主义革命和建设时期，党面临的主要任务是，实现从新民主主义到社会主义的转变，进行社会主义革命，推进社会主义建设，为实现中华民族伟大复兴奠定根本政治前提和制度基础\n\n③改革开放和社会主义现代化建设新时期，党面临的主要任务是，继续探索中国建设社会主义的正确道路，解放和发展社会生产力，使人民摆脱贫困、尽快富裕起来，为实现中华民族伟大复兴提供充满新的活力的体制保证和快速发展的物质条件\n\n④中国特色社会主义进入新时代，党面临的主要任务是，实现第一个百年奋斗目标开启实现第二个百年奋斗目标新征程，朝着实现中华民族伟大复兴的宏伟目标继续前进","options":[{"k":"A","t":"1 项"},{"k":"B","t":"2 项"},{"k":"C","t":"3 项"},{"k":"D","t":"4 项"}],"material":"","explanation":"1\n\n本题考查政治常识。\n\n十九届六中全会于2021年11月8日至11日在北京召开，并审议通过了《中共中央关于党的百年奋斗重大成就和历史经验的决议》。\n\n①项正确，全会提出，新民主主义革命时期，党面临的主要任务是，反对帝国主义、封建主义、官僚资本主义，争取民族独立、人民解放，为实现中华民族伟大复兴创造根本社会条件。\n\n②项正确，全会提出，社会主义革命和建设时期，党面临的主要任务是，实现从新民主主义到社会主义的转变，进行社会主义革命，推进社会主义建设，为实现中华民族伟大复兴奠定根本政治前提和制度基础。\n\n③项正确，全会提出，改革开放和社会主义现代化建设新时期，党面临的主要任务是，继续探索中国建设社会主义的正确道路，解放和发展社会生产力，使人民摆脱贫困、尽快富裕起来，为实现中华民族伟大复兴提供充满新的活力的体制保证和快速发展的物质条件。\n\n④项正确，全会提出，党的十八大以来，中国特色社会主义进入新时代。党面临的主要任务是，实现第一个百年奋斗目标，开启实现第二个百年奋斗目标新征程，朝着实现中华民族伟大复兴的宏伟目标继续前进。党领导人民自信自强、守正创新，创造了新时代中国特色社会主义的伟大成就。\n\n故正确答案为D。"},"from":{"file":"07-事业编职测/B类/2022/2022-05-21/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"政治常识","questionPages":[1],"answerPages":[1]},"idx":0,"pid":"pdeca4dd77c","sourceYears":[2022]},{"qid":"sy-b-20220521-002","no":2,"type":"政治常识","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"政治常识","tag":"未细分","confidence":"待复核","needsReview":true,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.unresolved","evidence":"④引导金融机构加大对实体经济特别是小微企业、科技创新、绿色发展的支持","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[1],"answer":[1]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-b-20220521-002-题目-p01-366-542.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"①②③"},{"k":"B","t":"①②④"},{"k":"C","t":"①③④"},{"k":"D","t":"②③④"}],"answer":"B","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-b-20220521-002-解析-p01-353-560.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"2021 年12 月8 日至10 日，中央经济工作会议在北京举行。下列选项中，符合会议所提出的宏观政策要求的是（ ）。\n\n①坚决遏制新增地方政府隐性债务\n\n②实施新的减税降费政策，适度超前开展基础设施投资\n\n③强化知识产权保护，营造国有制企业竞相发展的良好环境\n\n④引导金融机构加大对实体经济特别是小微企业、科技创新、绿色发展的支持","options":[{"k":"A","t":"①②③"},{"k":"B","t":"①②④"},{"k":"C","t":"①③④"},{"k":"D","t":"②③④"}],"material":"","explanation":"本题考查政治常识。\n\n2021年中央经济工作会议于2021年12月8日至10日在北京举行，会议要求如下：\n\n①项、②项、④项正确，一是宏观政策要稳健有效。要继续实施积极的财政政策和稳健的货币政策。积极的财政政策要提升效能，更加注重精准、可持续。要保证财政支出强度，加快支出进度。实施新的减税降费政策，强化对中小微企业、个体工商户、制造业、风险化解等的支持力度，适度超前开展基础设施投资。党政机关要坚持过紧日子。严肃财经纪律。坚决遇制新增地方政府隐性债务。稳健的货币政策要灵活适度，保持流动性合理充裕。引导金融机构加大对实体经济特别是小微企业、科技创新、绿色发展的支持。财政政策和货币政策要协调联动，跨周期和逆周期宏观调控政策要有机结合。实施好扩大内需战略，增强发展内生动力。\n\n③项错误，二是微观政策要持续激发市场主体活力。要提高市场主体信心，深入推进公平竞争政策实施，加强反断和反不正当竞争，以公正监管保障公平竞争。强化知识产权保护，营造各类所有制企业竞相发展的良好环境。强化契约精神，有效治理恶意拖欠账款和逃废债行为。\n\n故正确答案为B。"},"from":{"file":"07-事业编职测/B类/2022/2022-05-21/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"政治常识","questionPages":[1],"answerPages":[1]},"idx":1,"pid":"pdeca4dd77c","sourceYears":[2022]},{"qid":"sy-c-20220521-001","no":1,"type":"政治常识","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"政治常识","tag":"未细分","confidence":"待复核","needsReview":true,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.unresolved","evidence":"斗目标新征程，朝着实现中华民族伟大复兴的宏伟目标继续前进","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[1],"answer":[1]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20220521-001-题目-p01-116-370.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"1 项"},{"k":"B","t":"2 项"},{"k":"C","t":"3 项"},{"k":"D","t":"4 项"}],"answer":"D","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20220521-001-解析-p01-103-341.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"党的十九届六中全会审议通过了一份特别的“百年总结”——《中共中央关于党的百年奋斗重大成就和历史经验的决议》。在这份决议中，提到了党在各个历史时期的主要任务。对此，下列说法正确的有几项？（ ）\n\n①新民主主义革命时期，党面临的主要任务是，反对帝国主义、封建主义、官僚资本主义，争取民族独立、人民解放，为实现中华民族伟大复兴创造根本社会条件\n\n②社会主义革命和建设时期，党面临的主要任务是，实现从新民主主义到社会主义的转变，进行社会主义革命，推进社会主义建设，为实现中华民族伟大复兴奠定根本政治前提和制度基础\n\n③改革开放和社会主义现代化建设新时期，党面临的主要任务是，继续探索中国建设社会主义的正确道路，解放和发展社会生产力，使人民摆脱贫困、尽快富裕起来，为实现中华民族伟大复兴提供充满新的活力的体制保证和快速发展的物质条件\n\n④中国特色社会主义进入新时代，党面临的主要任务是，实现第一个百年奋斗目标开启实现第二个百年奋斗目标新征程，朝着实现中华民族伟大复兴的宏伟目标继续前进","options":[{"k":"A","t":"1 项"},{"k":"B","t":"2 项"},{"k":"C","t":"3 项"},{"k":"D","t":"4 项"}],"material":"","explanation":"1\n\n本题考查政治常识。\n\n十九届六中全会于2021年11月8日至11日在北京召开，并审议通过了《中共中央关于党的百年奋斗重大成就和历史经验的决议》。\n\n①项正确，全会提出，新民主主义革命时期，党面临的主要任务是，反对帝国主义、封建主义、官僚资本主义，争取民族独立、人民解放，为实现中华民族伟大复兴创造根本社会条件。\n\n②项正确，全会提出，社会主义革命和建设时期，党面临的主要任务是，实现从新民主主义到社会主义的转变，进行社会主义革命，推进社会主义建设，为实现中华民族伟大复兴奠定根本政治前提和制度基础。\n\n③项正确，全会提出，改革开放和社会主义现代化建设新时期，党面临的主要任务是，继续探索中国建设社会主义的正确道路，解放和发展社会生产力，使人民摆脱贫困、尽快富裕起来，为实现中华民族伟大复兴提供充满新的活力的体制保证和快速发展的物质条件。\n\n④项正确，全会提出，党的十八大以来，中国特色社会主义进入新时代。党面临的主要任务是，实现第一个百年奋斗目标，开启实现第二个百年奋斗目标新征程，朝着实现中华民族伟大复兴的宏伟目标继续前进。党领导人民自信自强、守正创新，创造了新时代中国特色社会主义的伟大成就。\n\n故正确答案为 D。"},"from":{"file":"07-事业编职测/C类/2022/2022-05-21/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"政治常识","questionPages":[1],"answerPages":[1]},"idx":0,"pid":"pd5f69523eb","sourceYears":[2022]},{"qid":"sy-c-20220521-002","no":2,"type":"政治常识","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"政治常识","tag":"未细分","confidence":"待复核","needsReview":true,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.unresolved","evidence":"④引导金融机构加大对实体经济特别是小微企业、科技创新、绿色发展的支持","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[1],"answer":[1]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20220521-002-题目-p01-366-542.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"①②③"},{"k":"B","t":"①②④"},{"k":"C","t":"①③④"},{"k":"D","t":"②③④"}],"answer":"B","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20220521-002-解析-p01-336-543.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"2021 年12 月8 日至10 日，中央经济工作会议在北京举行。下列选项中，符合会议所提出的宏观政策要求的是（ ）。\n\n①坚决遏制新增地方政府隐性债务\n\n②实施新的减税降费政策，适度超前开展基础设施投资\n\n③强化知识产权保护，营造国有制企业竞相发展的良好环境\n\n④引导金融机构加大对实体经济特别是小微企业、科技创新、绿色发展的支持","options":[{"k":"A","t":"①②③"},{"k":"B","t":"①②④"},{"k":"C","t":"①③④"},{"k":"D","t":"②③④"}],"material":"","explanation":"2\n\n本题考查政治常识。\n\n2021年中央经济工作会议于2021年12月8日至10日在北京举行，会议要求如下：\n\n①项、②项、④项正确，一是宏观政策要稳健有效。要继续实施积极的财政政策和稳健的货币政策。积极的财政政策要提升效能，更加注重精准、可持续。要保证财政支出强度，加快支出进度。实施新的减税降费政策，强化对中小微企业、个体工商户、制造业、风险化解等的支持力度，适度超前开展基础设施投资。党政机关要坚持过紧日子。严肃财经纪律。坚决遇制新增地方政府隐性债务。稳健的货币政策要灵活适度，保持流动性合理充裕。引导金融机构加大对实体经济特别是小微企业、科技创新、绿色发展的支持。财政政策和货币政策要协调联动，跨周期和逆周期宏观调控政策要有机结合。实施好扩大内需战略，增强发展内生动力。\n\n③项错误，二是微观政策要持续激发市场主体活力。要提高市场主体信心，深入推进公平竞争政策实施，加强反断和反不正当竞争，以公正监管保障公平竞争。强化知识产权保护，营造各类所有制企业竞相发展的良好环境。强化契约精神，有效治理恶意拖欠账款和逃废债行为。\n\n故正确答案为B。"},"from":{"file":"07-事业编职测/C类/2022/2022-05-21/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"政治常识","questionPages":[1],"answerPages":[1]},"idx":1,"pid":"pd5f69523eb","sourceYears":[2022]},{"qid":"sy-c-20220521-003","no":3,"type":"政治常识","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"政治常识","tag":"未细分","confidence":"待复核","needsReview":true,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.unresolved","evidence":"关于习近平总书记对健康中国的重要论述，下列说法不准确的是（ ）。","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[1],"answer":[1,2]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20220521-003-题目-p01-538-636.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"人民健康是人民幸福生活的基础"},{"k":"B","t":"预防是最经济最有效的健康策略"},{"k":"C","t":"中医是人类同疾病斗争的锐利武器"},{"k":"D","t":"把健康融入所有政策，人民共建共享"}],"answer":"C","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20220521-003-解析-p01-538-812.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-c-20220521-003-解析-p02-51-92.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"关于习近平总书记对健康中国的重要论述，下列说法不准确的是（ ）。","options":[{"k":"A","t":"人民健康是人民幸福生活的基础"},{"k":"B","t":"预防是最经济最有效的健康策略"},{"k":"C","t":"中医是人类同疾病斗争的锐利武器"},{"k":"D","t":"把健康融入所有政策，人民共建共享"}],"material":"","explanation":"3\n\n本题考查政治常识。\n\nA项正确，2021年3月23日，习近平总书记在福建考察时指出；“现代化最重要的指标还是人民健康，这是人民幸福生活的基础。把这件事抓牢，人民至上、生命至上应该是全党全社会必须牢牢树立的一个理念。”\n\nB项正确，2021年3月6日，习近平总书记看望参加全国政协十三届四次会议的医药卫生界、教育界委员时指出：人民健康是社会文明进步的基础，是民族昌盛和国家富强的重要标志。这次抗击新冠肺炎疫情的实践再次证明，预防是最经济最有效的健康策略。\n\nC项错误，2020年6月2日，习近平总书记主持召开专家学者座谈会时指出；中西医结合、中西药并用，是这次疫情防控的一大特点，也是中医药传承精华、守正创新的生动实践。要加强对中医药工作的组织领导，推动中西医药相互补充、协调发展。\n\nD项正确，2016年8月19日，习近平总书记在全国卫生与健康大会上指出：“新形势下，我国卫生与健康工作方针是：以基层为重点，以改革创新为动力，预防为主，中西医并重，把健康融入所有政策，人民共建共享。”“这个方针的根本点是坚持以人民为中心的发展思想，坚持为人民健康服务，这是我国卫生与健康事业必须一以贯之坚持的基本要求。”\n\n本题为选非题，故正确答案为C。"},"from":{"file":"07-事业编职测/C类/2022/2022-05-21/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"政治常识","questionPages":[1],"answerPages":[1,2]},"idx":2,"pid":"pd5f69523eb","sourceYears":[2022]},{"qid":"sy-c-20220521-004","no":4,"type":"政治常识","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"政治常识","tag":"未细分","confidence":"待复核","needsReview":true,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.unresolved","evidence":"①胸怀大局②自信开放③为国争光④迎难而上⑤追求卓越⑥共创未来⑦人民至上","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[1,2],"answer":[2]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20220521-004-题目-p01-631-812.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-c-20220521-004-题目-p02-51-90.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"①②④⑤⑥"},{"k":"B","t":"①③④⑤⑦"},{"k":"C","t":"②③④⑥⑦"},{"k":"D","t":"②③⑤⑥⑦"}],"answer":"A","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20220521-004-解析-p02-87-216.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"2022 年4 月8 日上午，北京冬奥会、冬残奥会总结表彰大会在人民大会堂隆重举行。中共中央总书记、国家主席、中央军委主席习近平出席大会并发表重要讲话阐述了北京冬奥精神。下列属于北京冬奥精神的是（ ）。\n\n①胸怀大局②自信开放③为国争光④迎难而上⑤追求卓越⑥共创未来⑦人民至上","options":[{"k":"A","t":"①②④⑤⑥"},{"k":"B","t":"①③④⑤⑦"},{"k":"C","t":"②③④⑥⑦"},{"k":"D","t":"②③⑤⑥⑦"}],"material":"","explanation":"4\n\n本题考查政治常识。\n\n2022年4月8日上午，北京冬奥会、冬残奥会总结表彰大会在人民大会堂隆重举行。中共中央总书记、国家主席、中央军委主席习近平出席大会并发表重要讲话。习总书记指出，北京冬奥会、冬残奥会广大参与者珍惜伟大时代赋予的机遇，在冬奥申办、筹办、举办的过程中，共同创造了北京冬奥精神。这个精神是：胸怀大局、自信开放、迎难而上、追求卓越、共创未来。\n\n故正确答案为 A。"},"from":{"file":"07-事业编职测/C类/2022/2022-05-21/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"政治常识","questionPages":[1,2],"answerPages":[2]},"idx":3,"pid":"pd5f69523eb","sourceYears":[2022]},{"qid":"sy-c-20220521-005","no":5,"type":"政治常识","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"政治常识","tag":"未细分","confidence":"待复核","needsReview":true,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.unresolved","evidence":"④我国形成了一整套相对完善的大飞机产业链条","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[2],"answer":[2]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20220521-005-题目-p02-85-246.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"1 项"},{"k":"B","t":"2 项"},{"k":"C","t":"3 项"},{"k":"D","t":"4 项"}],"answer":"C","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20220521-005-解析-p02-211-449.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"下列选项中，属于2021 年取得的科技进展的有（ ）项。\n\n①我国星际探测实现了从地月系到行星际的跨越\n\n②我国圆满完成空间站阶段航天员首次出舱活动\n\n③我国可控核聚变研究装置（“人造太阳”）建成\n\n④我国形成了一整套相对完善的大飞机产业链条","options":[{"k":"A","t":"1 项"},{"k":"B","t":"2 项"},{"k":"C","t":"3 项"},{"k":"D","t":"4 项"}],"material":"","explanation":"本题考查政治常识。\n\n①项正确，2021年5月15日，习近平代表党中央、国务院和中央军委致电祝贺我国首次火星探测任务天问一号探测器成功着陆火星，指出：“天问一号探测器着陆火星，迈出了我国星际探测征程的重要一步，实现了从地月系到行星际的跨越，在火星上首次留下中国人的印迹，这是我国航天事业发展的又一具有里程碑意义的进展。”\n\n②项正确，2021年7月4日14时57分，经过约7小时的出舱活动，神舟十二号航天员乘组密切协同，聂海胜作为我国空间站首个操控机械臂的航天员，顺利配合出舱活动完成作业点微调工作，舱外航天员刘伯明、汤洪波圆满完成出舱活动期间全部既定任务，安全返回天和核心舱，我国空间站阶段航天员首次出舱活动取得圆满成功。\n\n③项错误，我国新一代可控核聚变研究装置“中国环流器二号M”（HL-2M）于2020年12月4日在成都正式建成放电，标志我国正式跨入全球可控核聚变研究前列，HL-2M将进一步加快人类探索未来能源的步伐。\n\n④项正确，2021年4月24日，由我国自主设计建造的首个国产大飞机生产试飞中心一一中国商飞江西生产试飞中心24日全面工，标志着我国已形成从科研设计、生产试飞到交付运营一整套相对完善的大飞机产业链条。\n\n故正确答案为 C。"},"from":{"file":"07-事业编职测/C类/2022/2022-05-21/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"政治常识","questionPages":[2],"answerPages":[2]},"idx":4,"pid":"pd5f69523eb","sourceYears":[2022]},{"qid":"sy-a-20220917-001","no":1,"type":"政治常识","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"政治常识","tag":"未细分","confidence":"待复核","needsReview":true,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.unresolved","evidence":"⑧坚持弘扬科学家精神","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[1],"answer":[1]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-a-20220917-001-题目-p01-116-370.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"①②③④"},{"k":"B","t":"①⑥⑦⑧"},{"k":"C","t":"②③⑤⑥"},{"k":"D","t":"④⑤⑦⑧"}],"answer":"B","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-a-20220917-001-解析-p01-104-264.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"2021 年9 月27 日和28 日，中央人才工作会议在京召开，在这次会议上，习近平总书记首次系统概括提出了新时代人才工作的新理念新战略和新举措。\n\n下列选项中，属于这些新理念新战略和新举措的是（ ）。\n\n①坚持党对人才工作的全面领导\n\n②坚持人才优先发展战略\n\n③坚持面向经济主战场、面向绿色生态环境\n\n④坚持培养特殊领域人才\n\n⑤坚持科教兴国战略\n\n⑥坚持聚天下英才而用之\n\n⑦坚持营造识才爱才敬才用才的环境\n\n⑧坚持弘扬科学家精神","options":[{"k":"A","t":"①②③④"},{"k":"B","t":"①⑥⑦⑧"},{"k":"C","t":"②③⑤⑥"},{"k":"D","t":"④⑤⑦⑧"}],"material":"","explanation":"1\n\n本题考查政治常识。\n\n2021年9月27日至28日，中央人才工作会议在京召开，习近平指出，党的十八大以来，党中央深刻回答了为什么建设人才强国、什么是人才强国、怎样建设人才强国的重大理论和实践问题，提出了一系列新理念新战略新举措。一是坚持党对人才工作的全面领导，二是坚持人才引领发展的战略地位，三是坚持面向世界科技前沿、面向经济主战场、面向国家重大需求、面向人民生命健康，四是坚持全方位培养用好人才，五是坚持深化人才发展体制机制改革，六是坚持聚天下英才而用之，七是坚持营造识才爱才敬才用才的环境，八是坚持弘扬科学家精神。以上8条，是我们对我国人才事业发展规律性认识的深化，要始终坚持并不断丰富发展。\n\n故正确答案为B。"},"from":{"file":"07-事业编职测/A类/2022/2022-09-17/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"政治常识","questionPages":[1],"answerPages":[1]},"idx":0,"pid":"p13dc5264a7","sourceYears":[2022]},{"qid":"sy-a-20220917-002","no":2,"type":"政治常识","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"政治常识","tag":"未细分","confidence":"待复核","needsReview":true,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.unresolved","evidence":"④国内生产总值二季度实现正增长","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[1],"answer":[1]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-a-20220917-002-题目-p01-366-526.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"①②③"},{"k":"B","t":"①②④"},{"k":"C","t":"①③④"},{"k":"D","t":"②③④"}],"answer":"D","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-a-20220917-002-解析-p01-260-404.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"下列关于2022 年中国经济上半年运行情况的说法，正确的是（ ）。\n\n①经济增速快于人均可支配收入实际增速\n\n②全国城镇新增就业完成全年目标任务过半\n\n③外贸进出口连续8 个季度实现同比正增长\n\n④国内生产总值二季度实现正增长","options":[{"k":"A","t":"①②③"},{"k":"B","t":"①②④"},{"k":"C","t":"①③④"},{"k":"D","t":"②③④"}],"material":"","explanation":"本题考查政治常识。\n\n①2022年上半年，全国居民人均可支配收入同比实际增长3%，快于经济增速。\n\n②2022年7月22日人力资源和社会保障部召开2022年二季度新闻发布会。今年1至6月，城镇新增就业654万人，完成全年目标的59%，人才队伍建设持续加强。\n\n③2022年7月13日，国务院新闻办公室举行新闻发布会，今年上半年，我国外贸进出口稳步增长，已连续8个季度实现同比正增长，外贸规模稳中有增，达到19.8万亿元，为稳定宏观经济大盘作出了贡献。\n\n④2022年7月15日，中国经济上半年运行数据发布一一上半年国内生产总值同比增长2.5%；二季度经济实现正增长。\n\n故正确答案为 D。"},"from":{"file":"07-事业编职测/A类/2022/2022-09-17/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"政治常识","questionPages":[1],"answerPages":[1]},"idx":1,"pid":"p13dc5264a7","sourceYears":[2022]},{"qid":"sy-a-20220917-003","no":3,"type":"政治常识","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"政治常识","tag":"未细分","confidence":"待复核","needsReview":true,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.unresolved","evidence":"派驻村第一书记和工作队，下列说法正确的是（ ）。","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[1],"answer":[1]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-a-20220917-003-题目-p01-522-636.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"驻村期间，第一书记和工作队员不可参加村级组织换届选举"},{"k":"B","t":"第一书记和工作队员任期一般不少于5 年，到期轮换、压茬交接"},{"k":"C","t":"派出单位加强跟踪管理，每个月听取1 次第一书记和工作队员汇报"},{"k":"D","t":"第一书记和工作队员必须是中共正式党员，且有2 年以上工作经历"}],"answer":"A","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-a-20220917-003-解析-p01-400-608.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"2021 年5 月，中共中央办公厅印发了《关于向重点乡村持续选派驻村第一书记和工作队的意见》，关于选派驻村第一书记和工作队，下列说法正确的是（ ）。","options":[{"k":"A","t":"驻村期间，第一书记和工作队员不可参加村级组织换届选举"},{"k":"B","t":"第一书记和工作队员任期一般不少于5 年，到期轮换、压茬交接"},{"k":"C","t":"派出单位加强跟踪管理，每个月听取1 次第一书记和工作队员汇报"},{"k":"D","t":"第一书记和工作队员必须是中共正式党员，且有2 年以上工作经历"}],"material":"","explanation":"3\n\n本题考查政治常识。\n\nA项正确，《关于向重点乡村持续选派驻村第一书记和工作队的意见》指出：“驻村期间，第一书记和工作队员原人事关系、工资和福利待遇不变，不承担派出单位工作；党员组织关系转到村，不占村干部职数，一般不参加村级组织换届选举。”\n\nB项错误，《关于向重点乡村持续选派驻村第一书记和工作队的意见》指出：“第一书记和工作队员任期一般不少于2年，到期轮换、压茬交接。同步选派第一书记和工作队的村，队长由第一书记兼任，队员一般不少于2人，任务重的可适当增加人数。”\n\nC项错误，《关于向重点乡村持续选派驻村第一书记和工作队的意见》指出：“派出单位加强跟踪管理，每半年听取1次第一书记和工作队员汇报。”\n\nD项错误，《关于向重点乡村持续选派驻村第一书记和工作队的意见》指出：“第一书记必须是中共正式党员，具有1年以上党龄和2年以上工作经历；工作队员应优先选派中共党员。”\n\n故正确答案为 A。"},"from":{"file":"07-事业编职测/A类/2022/2022-09-17/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"政治常识","questionPages":[1],"answerPages":[1]},"idx":2,"pid":"p13dc5264a7","sourceYears":[2022]},{"qid":"sy-a-20220917-004","no":4,"type":"政治常识","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"政治常识","tag":"未细分","confidence":"待复核","needsReview":true,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.unresolved","evidence":"④梁振英","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[1,2],"answer":[1]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-a-20220917-004-题目-p01-631-812.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-a-20220917-004-题目-p02-51-105.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"①②③"},{"k":"B","t":"①②④"},{"k":"C","t":"①③④"},{"k":"D","t":"②③④"}],"answer":"C","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-a-20220917-004-解析-p01-603-748.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"2022 年是香港回归祖国25 周年，下列人物中，担任过香港特别行政区行政长官的有（ ）。\n\n①董建华\n\n②何厚铧\n\n③曾荫权\n\n④梁振英","options":[{"k":"A","t":"①②③"},{"k":"B","t":"①②④"},{"k":"C","t":"①③④"},{"k":"D","t":"②③④"}],"material":"","explanation":"4\n\n本题考查政治常识。\n\n①项正确，董建华，香港特别行政区首任行政长官，曾为贯彻落实“一国两制”方针和《中华人民共和国香港特别行政区基本法》作出重要贡献。\n\n②项错误，何厚铧，澳门第一、二任行政长官，并未担任过香港特别行政区行政长官。\n\n③项正确，曾荫权，香港特别行政区第二、三任行政长官。（注：第二任刚开始是董建华，任期未满以健康理由辞职，后曾荫权宣誓成为第二任行政长官）\n\n④项正确，梁振英，香港特别行政区第四任行政长官。\n\n故正确答案为 C。"},"from":{"file":"07-事业编职测/A类/2022/2022-09-17/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"政治常识","questionPages":[1,2],"answerPages":[1]},"idx":3,"pid":"p13dc5264a7","sourceYears":[2022]},{"qid":"sy-a-20220917-006","no":6,"type":"政治常识","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"政治常识","tag":"未细分","confidence":"待复核","needsReview":true,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.unresolved","evidence":"④我国第一艘货运飞船天舟一号发射升空，与在轨运行的天宫二号空间实验室完成交会对接","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[2],"answer":[2]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-a-20220917-006-题目-p02-210-370.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"1 项"},{"k":"B","t":"2 项"},{"k":"C","t":"3 项"},{"k":"D","t":"4 项"}],"answer":"D","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-a-20220917-006-解析-p02-291-530.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"下列关于我国“十三五”以来取得的航天成就的描述，正确的有几项（ ）。\n\n①嫦娥五号首次实现了我国地外天体采样返回，为我国未来月球与行星探测奠定了坚实基础\n\n②北斗三号全球卫星导航系统正式开通，我国成为世界上第三个独立拥有全球卫星导航系统的国家\n\n③我国首次执行火星探测任务的天问一号探测器正式启航，完成火星环绕、着陆、巡视探测三大任务\n\n④我国第一艘货运飞船天舟一号发射升空，与在轨运行的天宫二号空间实验室完成交会对接","options":[{"k":"A","t":"1 项"},{"k":"B","t":"2 项"},{"k":"C","t":"3 项"},{"k":"D","t":"4 项"}],"material":"","explanation":"6\n\n本题考查政治常识。\n\n①正确，2020年12月17日，嫦娥五号返回器携带月球样品，采用半弹道跳跃方式再入返回，在内蒙古四子王旗预定区域安全着陆，探月工程嫦娥五号任务取得圆满成功。嫦娥五号首次实现了我国地外天体采样返回，为我国未来月球与行星探测奠定了坚实基础。\n\n②正确，2020年6月23日，北斗三号最后一颗全球组网卫星在西昌卫星发射中心点火升空。2020年7月31日，北斗三号全球卫星导航系统正式开通，标志着我国成为世界上第三个独立拥有全球卫星导航系统的国家。\n\n③正确，2020年7月23日，执行中国首次火星探测任务的天问一号探测器在文昌航天发射场发射升空，其飞行目标是：在国际上首次通过一次发射，实现火星环绕、着陆、巡视探测，使中国成为世界上第二个独立掌握火星着陆巡视探测技术的国家。\n\n④正确，天舟一号是中国自主研制的第一艘货运飞船，是向天宫二号进行货物运输的地面后勤保障系统，也是中国载人航天工程“三步走”战略计划中“第二步”的收官之作。天舟一号于2017年4月20日发射，进入预定轨道；于2017年4月22日与天宫二号空间实验室完成首次对接；于2017年9月22日完成任务，进入大气层烧毁。\n\n故正确答案为D。"},"from":{"file":"07-事业编职测/A类/2022/2022-09-17/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"政治常识","questionPages":[2],"answerPages":[2]},"idx":5,"pid":"p13dc5264a7","sourceYears":[2022]},{"qid":"sy-a-20220917-007","no":7,"type":"政治常识","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"政治常识","tag":"未细分","confidence":"待复核","needsReview":true,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.unresolved","evidence":"关于第七次全国人口普查，下列说法正确的是（ ）。","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[2],"answer":[2]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-a-20220917-007-题目-p02-366-464.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"普查标准时点是2020 年12 月1 日零时"},{"k":"B","t":"不允许使用智能手机采集普查对象数据"},{"k":"C","t":"中部地区人口在全国人口中的占比上升"},{"k":"D","t":"家庭户规模较之上次人口普查继续缩小"}],"answer":"D","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-a-20220917-007-解析-p02-526-812.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"关于第七次全国人口普查，下列说法正确的是（ ）。","options":[{"k":"A","t":"普查标准时点是2020 年12 月1 日零时"},{"k":"B","t":"不允许使用智能手机采集普查对象数据"},{"k":"C","t":"中部地区人口在全国人口中的占比上升"},{"k":"D","t":"家庭户规模较之上次人口普查继续缩小"}],"material":"","explanation":"7\n\n本题考查政治常识。\n\nA项错误，根据《中华人民共和国统计法》和《全国人口普查条例》规定，国务院决定于2020年开展第七次全国人口普查。第七次全国人口普查的普查标准时点是2020年11月1日零时，彻查人口出生变动情况以及房屋情况。\n\nB项错误，第七次全国人口普查入户工作于2020年10月11日至12月10日期间进行，11月1日起正式开启。此次人口普查采取电子化方式开展普查登记，同时倡导普查对象自主填报的方式，鼓励大家使用手机等移动终端自行申报个人和家庭信息。此次普查采用互联网云技术、云服务和云应用部署，全流程加强对公民个人信息的保护，确保公民个人信息安全。\n\nC项错误，2021年5月11日，国家统计局发布的《第七次全国人口普查公报》显示，中部地区人口占25.83%，与2010年相比，中部地区人口所占比重下降0.79个百分点。人口向经济发达区域、城市群进一步集聚。\n\nD项正确，2021年5月11日，国家统计局发布的《第七次全国人口普查公报》显示，全国共有家庭户49416万户，平均每个家庭户的人口为2.62人，比2010年的3.10人减少0.48人。家庭户规模继续缩小，主要是受我国人口流动日趋频繁和住房条件改善年轻人婚后独立居住等因素的影响。\n\n故正确答案为D。"},"from":{"file":"07-事业编职测/A类/2022/2022-09-17/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"政治常识","questionPages":[2],"answerPages":[2]},"idx":6,"pid":"p13dc5264a7","sourceYears":[2022]},{"qid":"sy-a-20220917-010","no":10,"type":"政治常识","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"政治常识","tag":"未细分","confidence":"待复核","needsReview":true,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.unresolved","evidence":"④人是自然界的产物，是在他们的环境中并且和这个环境一起发展起来的","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[2,3],"answer":[3,4]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-a-20220917-010-题目-p02-647-812.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-a-20220917-010-题目-p03-51-121.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"1 项"},{"k":"B","t":"2 项"},{"k":"C","t":"3 项"},{"k":"D","t":"4 项"}],"answer":"C","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-a-20220917-010-解析-p03-571-812.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-a-20220917-010-解析-p04-51-218.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"下列马克思主义哲学观点在“共谋人与自然和谐共生之道”中得到体现的有几项（ ）。\n\n①人类应当合理地调节人与自然之间的物质变换\n\n②人的发展过程就是人与自然界相互作用的过程\n\n③人类通过生产生活的实践活动在自然界中印证了人类的存在\n\n④人是自然界的产物，是在他们的环境中并且和这个环境一起发展起来的","options":[{"k":"A","t":"1 项"},{"k":"B","t":"2 项"},{"k":"C","t":"3 项"},{"k":"D","t":"4 项"}],"material":"","explanation":"10\n\n本题考查政治常识。\n\n“共谋人与自然和谐共生之道”的内在支撑是“人与自然生命共同体”。换言之，正是由于人与自然是生命共同体这一显而易见或无可置疑的前提，我们必须把坚持人与自然和谐共生置于所有经济社会活动中的优先地位。\n\n①符合题意。马克思认为，应当合理地调节人与自然之间的物质变换，在最无愧于和最适合人类本性的条件下进行这种物质变换。就是人在对自然界进行获取资源或者说对自然改造的实践活动中，要合理调节两者的关系，遵循客观规律，要保持自然系统内平衡关系。\n\n②符合题意。人类生命存在及其延续首先是自然世界整体的长期与复杂运动演进的历史结果，而适宜的自然生态环境条件是人类作为生物物种繁衍生息的必须前提。同时，人类的所有现实性活动一一从个体的物质精神活动到社会的生产实践活动，都离不开所处其中的自然界。因此，人的发展过程就是人与自然界相互作用的过程。\n\n③不符合题意。马克思主义的实践观，不仅揭示了自然界和社会的物质统一性，而且阐明了实践在人类社会生活中的根本地位，人与自然的关系是在实践中形成的，人在实践活动中创造了人类社会，人类社会的存在和发展，又反过来影响和制约自然界，不断改变自然界。③更多强调的是实践的重要性，而题干侧重人与自然的关系，因此，不符合题意。\n\n④符合题意。恩格斯说：“人本身是自然界的产物，是在他们的环境中并和这个环境一起发展起来的”强调的就是人与自然的关系。人因自然而生，人与自然是一种共生关系，对自然的伤害最终会伤及人类自身。只有尊重自然规律，才能有效防止在开发利用自然上走弯路。\n\n因此，能得到体现的有3项。\n\n故正确答案为 C。"},"from":{"file":"07-事业编职测/A类/2022/2022-09-17/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"政治常识","questionPages":[2,3],"answerPages":[3,4]},"idx":9,"pid":"p13dc5264a7","sourceYears":[2022]},{"qid":"sy-c-20220917-001","no":1,"type":"政治常识","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"政治常识","tag":"未细分","confidence":"待复核","needsReview":true,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.unresolved","evidence":"④国内生产总值二季度实现正增长","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[1],"answer":[1]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20220917-001-题目-p01-116-277.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"①②③"},{"k":"B","t":"①②④"},{"k":"C","t":"①③④"},{"k":"D","t":"②③④"}],"answer":"D","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20220917-001-解析-p01-102-262.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"下列关于2022 年中国经济上半年运行情况的说法，正确的是（ ）。\n\n①经济增速快于人均可支配收入实际增速\n\n②全国城镇新增就业完成全年目标任务过半\n\n③外贸进出口连续8 个季度实现同比正增长\n\n④国内生产总值二季度实现正增长","options":[{"k":"A","t":"①②③"},{"k":"B","t":"①②④"},{"k":"C","t":"①③④"},{"k":"D","t":"②③④"}],"material":"","explanation":"1\n\n本题考查政治常识。\n\n①2022年上半年，全国居民人均可支配收入同比实际增长3%，快于经济增速。\n\n②2022年7月22日人力资源和社会保障部召开2022年二季度新闻发布会。今年1至6月，城镇新增就业654万人，完成全年目标的59%，人才队伍建设持续加强。\n\n③2022年7月13日，国务院新闻办公室举行新闻发布会，今年上半年，我国外贸进出口稳步增长，已连续8个季度实现同比正增长，外贸规模稳中有增，达到19.8万亿元，为稳定宏观经济大盘作出了贡献。\n\n④2022年7月15日，中国经济上半年运行数据发布一一上半年国内生产总值同比增长2.5%；二季度经济实现正增长。\n\n故正确答案为 D。"},"from":{"file":"07-事业编职测/C类/2022/2022-09-17/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"政治常识","questionPages":[1],"answerPages":[1]},"idx":0,"pid":"p43b2f27e6f","sourceYears":[2022]},{"qid":"sy-c-20220917-002","no":2,"type":"政治常识","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"政治常识","tag":"未细分","confidence":"待复核","needsReview":true,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.unresolved","evidence":"化战略，提升城镇化发展质量。下列关于我国城镇化的说法，错误的是（ ）。","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[1],"answer":[1]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20220917-002-题目-p01-272-386.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"放开放宽大型城市和超大型城市的落户限制"},{"k":"B","t":"我国推进的新型城镇化战略以人为核心"},{"k":"C","t":"增强特大城市中心城区科技创新策源功能"},{"k":"D","t":"引导金融资本加大对县城建设的投入力度"}],"answer":"A","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20220917-002-解析-p01-258-511.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"《中华人民共和国国民经济和社会发展第十四个五年规划和2035 年远景目标纲要》提出，要完善新型城镇化战略，提升城镇化发展质量。下列关于我国城镇化的说法，错误的是（ ）。","options":[{"k":"A","t":"放开放宽大型城市和超大型城市的落户限制"},{"k":"B","t":"我国推进的新型城镇化战略以人为核心"},{"k":"C","t":"增强特大城市中心城区科技创新策源功能"},{"k":"D","t":"引导金融资本加大对县城建设的投入力度"}],"material":"","explanation":"2\n\n本题考查政治常识。\n\nA项错误，2022年国家发展改革委发布《“十四五”新型城镇化实施方案》，方案明确，放开放宽除个别超大城市外的落户限制，试行以经常居住地登记户口制度。\n\nB项正确，2022年国家发展改革委发布《“十四五”新型城镇化实施方案》，方案指出，为深入贯彻《中华人民共和国国民经济和社会发展第十四个五年规划和2035年远景目标纲要》和《国家新型城镇化规划（2021-2035年）》，坚持走以人为本、四化同步、优化布局、生态文明、文化传承的中国特色新型城镇化道路，明确“十四五”时期深入推进以人为核心的新型城镇化战略的目标任务和政策举措，制定本实施方案。\n\nC项正确，2022年国家发展改革委发布《“十四五”新型城镇化实施方案》，方案明确，推动超大特大城市转变发展方式······优化提升中心城区功能，增强全球资源配置、科技创新策源、高端产业引领功能，率先形成以现代服务业为主体、先进制造业为支撑的产业结构，提高综合能级与国际竞争力。\n\nD项正确，2022年5月6日，中共中央办公厅、国务院办公厅《关于推进以县城为重要载体的城镇化建设的意见》公开发布。《意见》指出，引导社会资金参与县城建设，规范推广政府和社会资本合作模式，鼓励中央企业等参与县城建设。引入社会资本参与县城城镇化建设，可以充分激发市场主体活力，促进有效投资。\n\n本题为选非题，故正确答案为 A。"},"from":{"file":"07-事业编职测/C类/2022/2022-09-17/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"政治常识","questionPages":[1],"answerPages":[1]},"idx":1,"pid":"p43b2f27e6f","sourceYears":[2022]},{"qid":"sy-c-20220917-006","no":6,"type":"政治常识","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"政治常识","tag":"未细分","confidence":"待复核","needsReview":true,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.unresolved","evidence":"关于第七次全国人口普查，下列说法正确的是（ ）。","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[1,2],"answer":[2]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20220917-006-题目-p01-678-812.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-c-20220917-006-题目-p02-51-90.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"普查标准时点是2020 年12 月1 日零时"},{"k":"B","t":"不允许使用智能手机采集普查对象数据"},{"k":"C","t":"中部地区人口在全国人口中的占比上升"},{"k":"D","t":"家庭户规模较之上次人口普查继续缩小"}],"answer":"D","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20220917-006-解析-p02-336-574.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"关于第七次全国人口普查，下列说法正确的是（ ）。","options":[{"k":"A","t":"普查标准时点是2020 年12 月1 日零时"},{"k":"B","t":"不允许使用智能手机采集普查对象数据"},{"k":"C","t":"中部地区人口在全国人口中的占比上升"},{"k":"D","t":"家庭户规模较之上次人口普查继续缩小"}],"material":"","explanation":"6\n\n本题考查政治常识。\n\nA项错误，根据《中华人民共和国统计法》和《全国人口普查条例》规定，国务院决定于2020年开展第七次全国人口普查。第七次全国人口普查的普查标准时点是2020年11月1日零时，彻查人口出生变动情况以及房屋情况。\n\nB项错误，第七次全国人口普查入户工作于2020年10月11日至12月10日期间进行，11月1日起正式开启。此次人口普查采取电子化方式开展普查登记，同时倡导普查对象自主填报的方式，鼓励大家使用手机等移动终端自行申报个人和家庭信息。此次普查采用互联网云技术、云服务和云应用部署，全流程加强对公民个人信息的保护，确保公民个人信息安全。\n\nC项错误，2021年5月11日，国家统计局发布的《第七次全国人口普查公报》显示，中部地区人口占25.83%，与2010年相比，中部地区人口所占比重下降0.79个百分点。人口向经济发达区域、城市群进一步集聚。\n\nD项正确，2021年5月11日，国家统计局发布的《第七次全国人口普查公报》显示，全国共有家庭户49416万户，平均每个家庭户的人口为2.62人，比2010年的3.10人减少0.48人。家庭户规模继续缩小，主要是受我国人口流动日趋频繁和住房条件改善年轻人婚后独立居住等因素的影响。\n\n故正确答案为D。"},"from":{"file":"07-事业编职测/C类/2022/2022-09-17/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"政治常识","questionPages":[1,2],"answerPages":[2]},"idx":5,"pid":"p43b2f27e6f","sourceYears":[2022]},{"qid":"sy-c-20220917-019","no":19,"type":"政治常识","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"政治常识","tag":"未细分","confidence":"待复核","needsReview":true,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.unresolved","evidence":"④人是自然界的产物，是在他们的环境中并且和这个环境一起发展起来的","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[3],"answer":[6,7]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20220917-019-题目-p03-538-698.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"1 项"},{"k":"B","t":"2 项"},{"k":"C","t":"3 项"},{"k":"D","t":"4 项"}],"answer":"C","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20220917-019-解析-p06-632-812.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-c-20220917-019-解析-p07-51-277.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"下列马克思主义哲学观点在“共谋人与自然和谐共生之道”中得到体现的有几项（ ）。\n\n①人类应当合理地调节人与自然之间的物质变换\n\n②人的发展过程就是人与自然界相互作用的过程\n\n③人类通过生产生活的实践活动在自然界中印证了人类的存在\n\n④人是自然界的产物，是在他们的环境中并且和这个环境一起发展起来的","options":[{"k":"A","t":"1 项"},{"k":"B","t":"2 项"},{"k":"C","t":"3 项"},{"k":"D","t":"4 项"}],"material":"","explanation":"19\n\n本题考查政治常识。\n\n“共谋人与自然和谐共生之道”的内在支撑是“人与自然生命共同体”。换言之，正是由于人与自然是生命共同体这一显而易见或无可置疑的前提，我们必须把坚持人与自然和谐共生置于所有经济社会活动中的优先地位。\n\n①符合题意。马克思认为，应当合理地调节人与自然之间的物质变换，在最无愧于和最适合人类本性的条件下进行这种物质变换。就是人在对自然界进行获取资源或者说对自然改造的实践活动中，要合理调节两者的关系，遵循客观规律，要保持自然系统内平衡关系。\n\n②符合题意。人类生命存在及其延续首先是自然世界整体的长期与复杂运动演进的历史结果，而适宜的自然生态环境条件是人类作为生物物种繁衍生息的必须前提。同时，人类的所有现实性活动一一从个体的物质精神活动到社会的生产实践活动，都离不开所处其中的自然界。因此，人的发展过程就是人与自然界相互作用的过程。\n\n③不符合题意。马克思主义的实践观，不仅揭示了自然界和社会的物质统一性，而且阐明了实践在人类社会生活中的根本地位，人与自然的关系是在实践中形成的，人在实践活动中创造了人类社会，人类社会的存在和发展，又反过来影响和制约自然界，不断改变自然界。③更多强调的是实践的重要性，而题干侧重人与自然的关系，因此，不符合题意。\n\n④符合题意。恩格斯说：“人本身是自然界的产物，是在他们的环境中并和这个环境一起发展起来的”强调的就是人与自然的关系。人因自然而生，人与自然是一种共生关系，对自然的伤害最终会伤及人类自身。只有尊重自然规律，才能有效防止在开发利用自然上走弯路。\n\n因此，能得到体现的有3项。\n\n故正确答案为 C。"},"from":{"file":"07-事业编职测/C类/2022/2022-09-17/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"政治常识","questionPages":[3],"answerPages":[6,7]},"idx":18,"pid":"p43b2f27e6f","sourceYears":[2022]},{"qid":"sy-a-20221112-001","no":1,"type":"政治常识","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"政治常识","tag":"未细分","confidence":"待复核","needsReview":true,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.unresolved","evidence":"⑥走和平发展道路的现代化","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[1],"answer":[1]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-a-20221112-001-题目-p01-116-339.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"①②③④⑤"},{"k":"B","t":"①②③④⑥"},{"k":"C","t":"①③④⑤⑥"},{"k":"D","t":"②③④⑤⑥"}],"answer":"D","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-a-20221112-001-解析-p01-105-202.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"2022 年10 月16 日，习近平总书记在中国共产党第二十次全国代表大会上作了题为《高举中国特色社会主义伟大旗帜 为全面建设社会主义现代化国家而团结奋斗》的报告。报告指出，中国式现代化既有各国现代化的共同特征，更有基于自己国情的中国特色。这里提到的中国式现代化的中国特色有（ ）。\n\n①坚持高质量发展的社会主义现代化\n\n②人口规模巨大的现代化\n\n③全体人民共同富裕的现代化\n\n④物质文明和精神文明相协调的现代化\n\n⑤人与自然和谐共生的现代化\n\n⑥走和平发展道路的现代化","options":[{"k":"A","t":"①②③④⑤"},{"k":"B","t":"①②③④⑥"},{"k":"C","t":"①③④⑤⑥"},{"k":"D","t":"②③④⑤⑥"}],"material":"","explanation":"1\n\n本题考查政治常识。\n\n党的二十大报告指出：中国共产党领导的社会主义现代化，既有各国现代化的共同特征，更有基于自已国情的中国特色。中国式现代化是人口规模巨大的现代化，是全体人民共同富裕的现代化，是物质文明和精神文明相协调的现代化，是人与自然和谐共生的现代化，是走和平发展道路的现代化。\n\n故正确答案为D。"},"from":{"file":"07-事业编职测/A类/2022/2022-11-12/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"政治常识","questionPages":[1],"answerPages":[1]},"idx":0,"pid":"pa93bf878ee","sourceYears":[2022]},{"qid":"sy-a-20221112-002","no":2,"type":"政治常识","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"政治常识","tag":"未细分","confidence":"待复核","needsReview":true,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.unresolved","evidence":"⑥坚持发扬斗争精神","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[1],"answer":[1]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-a-20221112-002-题目-p01-335-558.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"①②③④⑤"},{"k":"B","t":"①②④⑤⑥"},{"k":"C","t":"①②③⑤⑥"},{"k":"D","t":"①②③④⑥"}],"answer":"B","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-a-20221112-002-解析-p01-198-296.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"习近平书记在中国共产党第二十次全国代表大会上所作的《高举中国特色社会主义伟大族帜为全面建设社会主义现代化国家而团结奋斗》报告中指出，前进道路上，必须牢牢把握五个重大原则。这五个重大原则是（ ）。\n\n①坚持和加强党的全面领导\n\n②坚持中国特色社会主义道路\n\n③坚持马克思主义指导\n\n④坚持以人民为中心的发展思想\n\n⑤坚持深化改革开放\n\n⑥坚持发扬斗争精神","options":[{"k":"A","t":"①②③④⑤"},{"k":"B","t":"①②④⑤⑥"},{"k":"C","t":"①②③⑤⑥"},{"k":"D","t":"①②③④⑥"}],"material":"","explanation":"2\n\n本题考查政治常识。\n\n党的二十大报告指出：全面建设社会主义现代化国家，是一项伟大而艰巨的事业，前途光明，任重道远。\n\n前进道路上，必须牢牢把握以下重大原则：坚持和加强党的全面领导，坚持中国特色社会主义道路，坚持以人民为中心的发展思想，坚持深化改革开放，坚持发扬斗争精神。\n\n故正确答案为B。"},"from":{"file":"07-事业编职测/A类/2022/2022-11-12/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"政治常识","questionPages":[1],"answerPages":[1]},"idx":1,"pid":"pa93bf878ee","sourceYears":[2022]},{"qid":"sy-a-20221112-006","no":6,"type":"政治常识","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"政治常识","tag":"未细分","confidence":"待复核","needsReview":true,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.unresolved","evidence":"⑧坚持人文交流","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[2],"answer":[2]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-a-20221112-006-题目-p02-194-448.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"①③④⑤⑥"},{"k":"B","t":"①②③⑤⑦"},{"k":"C","t":"①③⑤⑦⑧"},{"k":"D","t":"①②④⑥⑧"}],"answer":"A","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-a-20221112-006-解析-p02-291-436.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"习近平总书记在上海合作组织成员国元首理事会第二十二次会议上的讲话强调，这些年来，本组织成员国以两份纲领性文件为思想基石和行动指南，逐步成功探索出一条新型国际组织成长壮大之路，积累形成了一系列富有启示意义的重要成功经验。习近平总书记所阐释的重要成功经验有（ ）。\n\n①坚持政治互信\n\n②坚持务实合作\n\n③坚持平等相待\n\n④坚持互利合作\n\n⑤坚持公平正义\n\n⑥坚持开放包容\n\n⑦坚持相互支持\n\n⑧坚持人文交流","options":[{"k":"A","t":"①③④⑤⑥"},{"k":"B","t":"①②③⑤⑦"},{"k":"C","t":"①③⑤⑦⑧"},{"k":"D","t":"①②④⑥⑧"}],"material":"","explanation":"6\n\n本题考查政治常识。\n\n2022年9月16日，国家主席习近平在撒马尔罕出席上海合作组织成员国元首理事会第二十二次会议并发表重要讲话。讲话指出，今年适逢上海合作组织宪章签署20周年，成员国长期睦邻友好合作条约签署15周年。\n\n这些年来，本组织成员国以这两份纲领性文件为思想基石和行动指南，逐步成功探索出一条新型国际组织成长壮大之路，积累形成了一系列富有启示意义的重要成功经验。要坚持政治互信；坚持互利合作；坚持平等相待；\n\n坚持开放包容；坚持公平正义。上述5点经验充分体现了互信、互利、平等、协商、尊重多样文明、谋求共同发展的“上海精神”。\n\n故正确答案为A。"},"from":{"file":"07-事业编职测/A类/2022/2022-11-12/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"政治常识","questionPages":[2],"answerPages":[2]},"idx":5,"pid":"pa93bf878ee","sourceYears":[2022]},{"qid":"sy-a-20221112-007","no":7,"type":"政治常识","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"政治常识","tag":"未细分","confidence":"待复核","needsReview":true,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.unresolved","evidence":"中国特色社会主义制度最大的优势是（ ）。","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[2],"answer":[2]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-a-20221112-007-题目-p02-444-542.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"中国共产党领导"},{"k":"B","t":"马克思主义理论"},{"k":"C","t":"坚持人民主体地位"},{"k":"D","t":"促进共同富裕"}],"answer":"A","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-a-20221112-007-解析-p02-432-530.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"中国特色社会主义制度最大的优势是（ ）。","options":[{"k":"A","t":"中国共产党领导"},{"k":"B","t":"马克思主义理论"},{"k":"C","t":"坚持人民主体地位"},{"k":"D","t":"促进共同富裕"}],"material":"","explanation":"7\n\n本题考查政治常识。\n\n中国特色主义制度最大的优势是中国共产党的领导。中国特色社会主义制度是党和人民在长期实践探索中形成的科学制度体系，我国国家治理一切工作和活动都依照中国特色社会主义制度展开，我国国家治理体系和治理能力是中国特色社会主义制度及其执行能力的集中体现。\n\n故正确答案为A。"},"from":{"file":"07-事业编职测/A类/2022/2022-11-12/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"政治常识","questionPages":[2],"answerPages":[2]},"idx":6,"pid":"pa93bf878ee","sourceYears":[2022]},{"qid":"sy-a-20221112-016","no":16,"type":"政治常识","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"政治常识","tag":"未细分","confidence":"待复核","needsReview":true,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.unresolved","evidence":"根据我国《“十四五”智能制造发展规划》，下列不属于智能制造示范工厂建设行动内容的是（ ）。","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[3,4],"answer":[5]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-a-20221112-016-题目-p03-662-812.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-a-20221112-016-题目-p04-51-136.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"甲公司在推动人工智能、大数据、区块链和虚拟现实等新技术在车间内制造环节进行深度应用，探索“人工智能 ”等智能场景应用"},{"k":"B","t":"乙钢铁公司围绕设计、生产、管理、服务等环节开展智能化升级，强化精益生产，打造智能工厂"},{"k":"C","t":"丙公司开发企业资源计划系统、供应链管理系统、客户关系管理系统、人力资源管理系统等工业软件系统"},{"k":"D","t":"丁公司的生产车间开展工艺革新，推动设备联网、生产环节数字化连接，强化标准作业、可视化管控、精准配送和最优库存，打造智能车间"}],"answer":"C","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-a-20221112-016-解析-p05-258-559.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"根据我国《“十四五”智能制造发展规划》，下列不属于智能制造示范工厂建设行动内容的是（ ）。","options":[{"k":"A","t":"甲公司在推动人工智能、大数据、区块链和虚拟现实等新技术在车间内制造环节进行深度应用，探索“人工智能 ”等智能场景应用"},{"k":"B","t":"乙钢铁公司围绕设计、生产、管理、服务等环节开展智能化升级，强化精益生产，打造智能工厂"},{"k":"C","t":"丙公司开发企业资源计划系统、供应链管理系统、客户关系管理系统、人力资源管理系统等工业软件系统"},{"k":"D","t":"丁公司的生产车间开展工艺革新，推动设备联网、生产环节数字化连接，强化标准作业、可视化管控、精准配送和最优库存，打造智能车间"}],"material":"","explanation":"16\n\n本题考查政治常识。\n\n面对不断升级的智能制造发展需求，《“十四五”智能制造发展规划》专门部署了“智能制造示范工厂建设行动”，推动“场景一车间一工厂一供应链”的智能化改造，探索智能制造最佳实践的标准化、模块化、精准化的推广路径。\n\n智能制造示范工厂建设行动包括：\n\n①智能场景。推动数字李生、人工智能、5G、大数据、区块链、虚拟现实(VR)/增强现实(AR)/混合现实(MR)等新技术在制造环节的深度应用，探索形成一批“数字李生”十“人工智能十”“虚拟/增强/混合现实(XR)+”等智能场景。\n\n②智能车间。覆盖加工、检测、物流等环节，开展工艺改进和革新，推动设备联网和生产环节数字化连接，强化标准作业、可视管控、精准配送、最优库存，打造一批智能车间，实现生产数据贯通化、制造柔性化和管理智能化。\n\n③智能工厂。支持基础条件好的企业，围绕设计、生产、管理、服务等制造全过程开展智能化升级，优化组织结构和业务流程，强化精益生产，打造一批智能工厂，推动跨业务活动的数据共享和深度挖掘，实现对核心业务的精准预测、管理优化和自主决策。\n\n④智慧供应链。面向汽车、工程机械、轨道交通装备、航空航天装备、船舶与海洋工程装备、电力装备、医疗装备、家用电器、集成电路等行业，支持智能制造应用水平高、核心竞争优势突出、资源配置能力强的龙头企业建设供应链协同平台，打造数据互联互通、信息可信交互、生产深度协同、资源柔性配置的供应链。\n\n本题为选非题，故正确答案为C。"},"from":{"file":"07-事业编职测/A类/2022/2022-11-12/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"政治常识","questionPages":[3,4],"answerPages":[5]},"idx":15,"pid":"pa93bf878ee","sourceYears":[2022]},{"qid":"sy-b-20221112-001","no":1,"type":"政治常识","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"政治常识","tag":"未细分","confidence":"待复核","needsReview":true,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.unresolved","evidence":"⑥走和平发展道路的现代化","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[1],"answer":[1]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-b-20221112-001-题目-p01-116-339.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"①②③④⑤"},{"k":"B","t":"①②③④⑥"},{"k":"C","t":"①③④⑤⑥"},{"k":"D","t":"②③④⑤⑥"}],"answer":"D","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-b-20221112-001-解析-p01-105-202.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"2022 年10 月16 日，习近平总书记在中国共产党第二十次全国代表大会上作了题为《高举中国特色社会主义伟大旗帜 为全面建设社会主义现代化国家而团结奋斗》的报告。报告指出，中国式现代化既有各国现代化的共同特征，更有基于自己国情的中国特色。这里提到的中国式现代化的中国特色有（ ）。\n\n①坚持高质量发展的社会主义现代化\n\n②人口规模巨大的现代化\n\n③全体人民共同富裕的现代化\n\n④物质文明和精神文明相协调的现代化\n\n⑤人与自然和谐共生的现代化\n\n⑥走和平发展道路的现代化","options":[{"k":"A","t":"①②③④⑤"},{"k":"B","t":"①②③④⑥"},{"k":"C","t":"①③④⑤⑥"},{"k":"D","t":"②③④⑤⑥"}],"material":"","explanation":"1\n\n本题考查政治常识。\n\n党的二十大报告指出：中国共产党领导的社会主义现代化，既有各国现代化的共同特征，更有基于自已国情的中国特色。中国式现代化是人口规模巨大的现代化，是全体人民共同富裕的现代化，是物质文明和精神文明相协调的现代化，是人与自然和谐共生的现代化，是走和平发展道路的现代化。\n\n故正确答案为D。"},"from":{"file":"07-事业编职测/B类/2022/2022-11-12/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"政治常识","questionPages":[1],"answerPages":[1]},"idx":0,"pid":"p9bf4bfded4","sourceYears":[2022]},{"qid":"sy-b-20221112-002","no":2,"type":"政治常识","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"政治常识","tag":"未细分","confidence":"待复核","needsReview":true,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.unresolved","evidence":"没有用以阐释“一带一路”的是（ ）。","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[1],"answer":[1]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-b-20221112-002-题目-p01-335-448.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"落其实者思其树，饮其流者怀其源"},{"k":"B","t":"与君远相知，不道云海深"},{"k":"C","t":"积力之所举，则无不胜也；众智之所为，则无不成也"},{"k":"D","t":"万物并育而不相害，道并行而不相悖"}],"answer":"A","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-b-20221112-002-解析-p01-198-452.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"习近平总书记在不同场合多次引用中国古语来阐释“一带一路”的丰富内涵。下列古语中，习近平总书记没有用以阐释“一带一路”的是（ ）。","options":[{"k":"A","t":"落其实者思其树，饮其流者怀其源"},{"k":"B","t":"与君远相知，不道云海深"},{"k":"C","t":"积力之所举，则无不胜也；众智之所为，则无不成也"},{"k":"D","t":"万物并育而不相害，道并行而不相悖"}],"material":"","explanation":"2\n\n本题考查政治常识。\n\nA项错误，“落其实者思其树，饮其流者怀其源”，是2016年11月30日习近平总书记在中国文学艺术界联合会第十次全国代表大会、中国作家协会第九次全国代表大会开幕式上讲话时引用的。习总书记说：“中华文化既是历史的、也是当代的，既是民族的、也是世界的。只有扎根脚下这块生于斯、长于斯的土地，文艺才能接住地气、增加底气、灌注生气，在世界文化激荡中站稳脚跟。主要体现中华文化。\n\nB项正确，“与君远相知，不道云海深”，是4月20日，习近平总书记在博鳌亚洲论坛2021年年会开幕式上发表主旨演讲。意思是尽管相隔千里万里，但是只要能够相互了解、彼此相知，再深远辽阔的云海也不会将你我分开。\n\nC项正确，“积力之所举，则无不胜也；众智之所为，则无不成也”这句名言，是2017年1月17日，习近平总书记在世界经济论坛2017年年会开幕式上发表主旨演讲时引用的。只要我们牢固树立人类命运共同体意识，携手努力、共同担当，同舟共济、共渡难关，就一定能够让世界更美好、让人民更幸福。\n\nD项正确，“万物并育而不相害，道并行而不相悸”是习近平总书记在纪念马克思诞辰200周年大会上发表重要讲话时使用的。习近平总书记指出，今天，人类交往的世界性比过去任何时候都更深入、更广泛，各国相互联系和彼此依存比过去任何时候都更频繁、更紧密。\n\n本题为选非题，故正确答案为A。"},"from":{"file":"07-事业编职测/B类/2022/2022-11-12/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"政治常识","questionPages":[1],"answerPages":[1]},"idx":1,"pid":"p9bf4bfded4","sourceYears":[2022]},{"qid":"sy-b-20221112-003","no":3,"type":"政治常识","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"政治常识","tag":"未细分","confidence":"待复核","needsReview":true,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.unresolved","evidence":"中国特色社会主义制度最大的优势是（ ）。","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[1],"answer":[1]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-b-20221112-003-题目-p01-444-542.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"中国共产党领导"},{"k":"B","t":"马克思主义理论"},{"k":"C","t":"坚持人民主体地位"},{"k":"D","t":"促进共同富裕"}],"answer":"A","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-b-20221112-003-解析-p01-448-560.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"中国特色社会主义制度最大的优势是（ ）。","options":[{"k":"A","t":"中国共产党领导"},{"k":"B","t":"马克思主义理论"},{"k":"C","t":"坚持人民主体地位"},{"k":"D","t":"促进共同富裕"}],"material":"","explanation":"3\n\n本题考查政治常识。\n\n中国特色主义制度最大的优势是中国共产党的领导。中国特色社会主义制度是党和人民在长期实践探索中形成的科学制度体系，我国国家治理一切工作和活动都依照中国特色社会主义制度展开，我国国家治理体系和治理能力是中国特色社会主义制度及其执行能力的集中体现。\n\n故正确答案为A。"},"from":{"file":"07-事业编职测/B类/2022/2022-11-12/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"政治常识","questionPages":[1],"answerPages":[1]},"idx":2,"pid":"p9bf4bfded4","sourceYears":[2022]},{"qid":"sy-b-20221112-007","no":7,"type":"政治常识","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"政治常识","tag":"未细分","confidence":"待复核","needsReview":true,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.unresolved","evidence":"根据我国《“十四五”智能制造发展规划》，下列不属于智能制造示范工厂建设行动内容的是（ ）。","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[2],"answer":[2,3]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-b-20221112-007-题目-p02-163-308.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"甲公司在推动人工智能、大数据、区块链和虚拟现实等新技术在车间内制造环节进行深度应用，探索“人工智能 ”等智能场景应用"},{"k":"B","t":"乙钢铁公司围绕设计、生产、管理、服务等环节开展智能化升级，强化精益生产，打造智能工厂"},{"k":"C","t":"丙公司开发企业资源计划系统、供应链管理系统、客户关系管理系统、人力资源管理系统等工业软件系统"},{"k":"D","t":"丁公司的生产车间开展工艺革新，推动设备联网、生产环节数字化连接，强化标准作业、可视化管控、精准配送和最优库存，打造智能车间"}],"answer":"C","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-b-20221112-007-解析-p02-525-812.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-b-20221112-007-解析-p03-51-140.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"根据我国《“十四五”智能制造发展规划》，下列不属于智能制造示范工厂建设行动内容的是（ ）。","options":[{"k":"A","t":"甲公司在推动人工智能、大数据、区块链和虚拟现实等新技术在车间内制造环节进行深度应用，探索“人工智能 ”等智能场景应用"},{"k":"B","t":"乙钢铁公司围绕设计、生产、管理、服务等环节开展智能化升级，强化精益生产，打造智能工厂"},{"k":"C","t":"丙公司开发企业资源计划系统、供应链管理系统、客户关系管理系统、人力资源管理系统等工业软件系统"},{"k":"D","t":"丁公司的生产车间开展工艺革新，推动设备联网、生产环节数字化连接，强化标准作业、可视化管控、精准配送和最优库存，打造智能车间"}],"material":"","explanation":"本题考查政治常识。\n\n面对不断升级的智能制造发展需求，《“十四五”智能制造发展规划》专门部署了“智能制造示范工厂建设行动”，推动“场景一车间一工厂一供应链”的智能化改造，探索智能制造最佳实践的标准化、模块化、精准化的推广路径。\n\n智能制造示范工厂建设行动包括：\n\n①智能场景。推动数字李生、人工智能、5G、大数据、区块链、虚拟现实(VR)/增强现实(AR)/混合现实(MR)等新技术在制造环节的深度应用，探索形成一批“数字李生”十“人工智能十”“虚拟/增强/混合现实(XR)+”等智能场景。\n\n②智能车间。覆盖加工、检测、物流等环节，开展工艺改进和革新，推动设备联网和生产环节数字化连接，强化标准作业、可视管控、精准配送、最优库存，打造一批智能车间，实现生产数据贯通化、制造柔性化和管理智能化。\n\n③智能工厂。支持基础条件好的企业，围绕设计、生产、管理、服务等制造全过程开展智能化升级，优化组织结构和业务流程，强化精益生产，打造一批智能工厂，推动跨业务活动的数据共享和深度挖掘，实现对核心业务的精准预测、管理优化和自主决策。\n\n①智慧供应链。面向汽车、工程机械、轨道交通装备、航空航天装备、船舶与海洋工程装备、电力装备、医疗装备、家用电器、集成电路等行业，支持智能制造应用水平高、核心竞争优势突出、资源配置能力强的龙头企业建设供应链协同平台，打造数据互联互通、信息可信交互、生产深度协同、资源柔性配置的供应链。\n\n本题为选非题，故正确答案为C。"},"from":{"file":"07-事业编职测/B类/2022/2022-11-12/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"政治常识","questionPages":[2],"answerPages":[2,3]},"idx":6,"pid":"p9bf4bfded4","sourceYears":[2022]},{"qid":"sy-c-20221112-001","no":1,"type":"政治常识","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"政治常识","tag":"未细分","confidence":"待复核","needsReview":true,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.unresolved","evidence":"⑥走和平发展道路的现代化","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[1],"answer":[1]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20221112-001-题目-p01-116-339.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"①②③④⑤"},{"k":"B","t":"①②③④⑥"},{"k":"C","t":"①③④⑤⑥"},{"k":"D","t":"②③④⑤⑥"}],"answer":"D","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20221112-001-解析-p01-103-200.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"2022年10月16日，习近平总书记在中国共产党第二十次全国代表大会上作了题为《高举中国特色社会主义伟大旗帜 为全面建设社会主义现代化国家而团结奋斗》的报告。报告指出，中国式现代化既有各国现代化的共同特征，更有基于自己国情的中国特色。这里提到的中国式现代化的中国特色有（ ）。\n\n①坚持高质量发展的社会主义现代化\n\n②人口规模巨大的现代化\n\n③全体人民共同富裕的现代化\n\n④物质文明和精神文明相协调的现代化\n\n⑤人与自然和谐共生的现代化\n\n⑥走和平发展道路的现代化","options":[{"k":"A","t":"①②③④⑤"},{"k":"B","t":"①②③④⑥"},{"k":"C","t":"①③④⑤⑥"},{"k":"D","t":"②③④⑤⑥"}],"material":"","explanation":"1\n\n本题考查政治常识。\n\n党的二十大报告指出：中国共产党领导的社会主义现代化，既有各国现代化的共同特征，更有基于自已国情的中国特色。中国式现代化是人口规模巨大的现代化，是全体人民共同富裕的现代化，是物质文明和精神文明相协调的现代化，是人与自然和谐共生的现代化，是走和平发展道路的现代化。\n\n故正确答案为D。"},"from":{"file":"07-事业编职测/C类/2022/2022-11-12/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"政治常识","questionPages":[1],"answerPages":[1]},"idx":0,"pid":"p2065d6d72f","sourceYears":[2022]},{"qid":"sy-c-20221112-002","no":2,"type":"政治常识","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"政治常识","tag":"未细分","confidence":"待复核","needsReview":true,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.unresolved","evidence":"⑥坚持发扬斗争精神","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[1],"answer":[1]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20221112-002-题目-p01-335-558.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"①②③④⑤"},{"k":"B","t":"①②④⑤⑥"},{"k":"C","t":"①②③⑤⑥"},{"k":"D","t":"①②③④⑥"}],"answer":"B","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20221112-002-解析-p01-196-294.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"习近平书记在中国共产党第二十次全国代表大会上所作的《高举中国特色社会主义伟大族帜为全面建设社会主义现代化国家而团结奋斗》报告中指出，前进道路上，必须牢牢把握五个重大原则。这五个重大原则是（ ）。\n\n①坚持和加强党的全面领导\n\n②坚持中国特色社会主义道路\n\n③坚持马克思主义指导\n\n④坚持以人民为中心的发展思想\n\n⑤坚持深化改革开放\n\n⑥坚持发扬斗争精神","options":[{"k":"A","t":"①②③④⑤"},{"k":"B","t":"①②④⑤⑥"},{"k":"C","t":"①②③⑤⑥"},{"k":"D","t":"①②③④⑥"}],"material":"","explanation":"2\n\n本题考查政治常识。\n\n党的二十大报告指出：全面建设社会主义现代化国家，是一项伟大而艰巨的事业，前途光明，任重道远。\n\n前进道路上，必须牢牢把握以下重大原则：坚持和加强党的全面领导，坚持中国特色社会主义道路，坚持以人民为中心的发展思想，坚持深化改革开放，坚持发扬斗争精神。\n\n故正确答案为B。"},"from":{"file":"07-事业编职测/C类/2022/2022-11-12/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"政治常识","questionPages":[1],"answerPages":[1]},"idx":1,"pid":"p2065d6d72f","sourceYears":[2022]},{"qid":"sy-c-20221112-003","no":3,"type":"政治常识","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"政治常识","tag":"未细分","confidence":"待复核","needsReview":true,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.unresolved","evidence":"没有用以阐释“一带一路”的是（ ）。","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[1],"answer":[1]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20221112-003-题目-p01-553-667.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"落其实者思其树，饮其流者怀其源"},{"k":"B","t":"与君远相知，不道云海深"},{"k":"C","t":"积力之所举，则无不胜也；众智之所为，则无不成也"},{"k":"D","t":"万物并育而不相害，道并行而不相悖"}],"answer":"A","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20221112-003-解析-p01-290-543.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"习近平总书记在不同场合多次引用中国古语来阐释“一带一路”的丰富内涵。下列古语中，习近平总书记没有用以阐释“一带一路”的是（ ）。","options":[{"k":"A","t":"落其实者思其树，饮其流者怀其源"},{"k":"B","t":"与君远相知，不道云海深"},{"k":"C","t":"积力之所举，则无不胜也；众智之所为，则无不成也"},{"k":"D","t":"万物并育而不相害，道并行而不相悖"}],"material":"","explanation":"3\n\n本题考查政治常识。\n\nA项错误，“落其实者思其树，饮其流者怀其源”，是2016年11月30日习近平总书记在中国文学艺术界联合会第十次全国代表大会、中国作家协会第九次全国代表大会开幕式上讲话时引用的。习总书记说：“中华文化既是历史的、也是当代的，既是民族的、也是世界的。只有扎根脚下这块生于斯、长于斯的土地，文艺才能接住地气、增加底气、灌注生气，在世界文化激荡中站稳脚跟。主要体现中华文化。\n\nB项正确，“与君远相知，不道云海深”，是4月20日，习近平总书记在博鳌亚洲论坛2021年年会开幕式上发表主旨演讲。意思是尽管相隔千里万里，但是只要能够相互了解、彼此相知，再深远辽阔的云海也不会将你我分开。\n\nC项正确，“积力之所举，则无不胜也；众智之所为，则无不成也”这句名言，是2017年1月17日，习近平总书记在世界经济论坛2017年年会开幕式上发表主旨演讲时引用的。只要我们牢固树立人类命运共同体意识，携手努力、共同担当，同舟共济、共渡难关，就一定能够让世界更美好、让人民更幸福。\n\nD项正确，“万物并育而不相害，道并行而不相悖”是习近平总书记在纪念马克思诞辰200周年大会上发表重要讲话时使用的。习近平总书记指出，今天，人类交往的世界性比过去任何时候都更深入、更广泛，各国相互联系和彼此依存比过去任何时候都更频繁、更紧密。\n\n本题为选非题，故正确答案为A。"},"from":{"file":"07-事业编职测/C类/2022/2022-11-12/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"政治常识","questionPages":[1],"answerPages":[1]},"idx":2,"pid":"p2065d6d72f","sourceYears":[2022]},{"qid":"sy-c-20221112-006","no":6,"type":"政治常识","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"政治常识","tag":"未细分","confidence":"待复核","needsReview":true,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.unresolved","evidence":"⑧坚持人文交流","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[2],"answer":[2]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20221112-006-题目-p02-194-448.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"①③④⑤⑥"},{"k":"B","t":"①②③⑤⑦"},{"k":"C","t":"①③⑤⑦⑧"},{"k":"D","t":"①②④⑥⑧"}],"answer":"A","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20221112-006-解析-p02-352-496.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"习近平总书记在上海合作组织成员国元首理事会第二十二次会议上的讲话强调，这些年来，本组织成员国以两份纲领性文件为思想基石和行动指南，逐步成功探索出一条新型国际组织成长壮大之路，积累形成了一系列富有启示意义的重要成功经验。习近平总书记所阐释的重要成功经验有（ ）。\n\n①坚持政治互信\n\n②坚持务实合作\n\n③坚持平等相待\n\n④坚持互利合作\n\n⑤坚持公平正义\n\n⑥坚持开放包容\n\n⑦坚持相互支持\n\n⑧坚持人文交流","options":[{"k":"A","t":"①③④⑤⑥"},{"k":"B","t":"①②③⑤⑦"},{"k":"C","t":"①③⑤⑦⑧"},{"k":"D","t":"①②④⑥⑧"}],"material":"","explanation":"6\n\n本题考查政治常识。\n\n2022年9月16日，国家主席习近平在撒马尔罕出席上海合作组织成员国元首理事会第二十二次会议并发表重要讲话。讲话指出，今年适逢上海合作组织宪章签署20周年，成员国长期睦邻友好合作条约签署15周年。\n\n这些年来，本组织成员国以这两份纲领性文件为思想基石和行动指南，逐步成功探索出一条新型国际组织成长壮大之路，积累形成了一系列富有启示意义的重要成功经验。要坚持政治互信；坚持互利合作；坚持平等相待；\n\n坚持开放包容；坚持公平正义。上述5点经验充分体现了互信、互利、平等、协商、尊重多样文明、谋求共同发展的“上海精神”。\n\n故正确答案为 A。"},"from":{"file":"07-事业编职测/C类/2022/2022-11-12/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"政治常识","questionPages":[2],"answerPages":[2]},"idx":5,"pid":"p2065d6d72f","sourceYears":[2022]},{"qid":"sy-c-20221112-007","no":7,"type":"政治常识","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"政治常识","tag":"未细分","confidence":"待复核","needsReview":true,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.unresolved","evidence":"中国特色社会主义制度最大的优势是（ ）。","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[2],"answer":[2]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20221112-007-题目-p02-444-542.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"中国共产党领导"},{"k":"B","t":"马克思主义理论"},{"k":"C","t":"坚持人民主体地位"},{"k":"D","t":"促进共同富裕"}],"answer":"A","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20221112-007-解析-p02-492-590.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"中国特色社会主义制度最大的优势是（ ）。","options":[{"k":"A","t":"中国共产党领导"},{"k":"B","t":"马克思主义理论"},{"k":"C","t":"坚持人民主体地位"},{"k":"D","t":"促进共同富裕"}],"material":"","explanation":"7\n\n本题考查政治常识。\n\n中国特色主义制度最大的优势是中国共产党的领导。中国特色社会主义制度是党和人民在长期实践探索中形成的科学制度体系，我国国家治理一切工作和活动都依照中国特色社会主义制度展开，我国国家治理体系和治理能力是中国特色社会主义制度及其执行能力的集中体现。\n\n故正确答案为 A。"},"from":{"file":"07-事业编职测/C类/2022/2022-11-12/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"政治常识","questionPages":[2],"answerPages":[2]},"idx":6,"pid":"p2065d6d72f","sourceYears":[2022]},{"qid":"sy-c-20221112-017","no":17,"type":"政治常识","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"政治常识","tag":"未细分","confidence":"待复核","needsReview":true,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.unresolved","evidence":"根据我国《“十四五”智能制造发展规划》，下列不属于智能制造示范工厂建设行动内容的是（ ）。","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[4],"answer":[5,6]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20221112-017-题目-p04-85-230.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"甲公司在推动人工智能、大数据、区块链和虚拟现实等新技术在车间内制造环节进行深度应用，探索“人工智能 ”等智能场景应用"},{"k":"B","t":"乙钢铁公司围绕设计、生产、管理、服务等环节开展智能化升级，强化精益生产，打造智能工厂"},{"k":"C","t":"丙公司开发企业资源计划系统、供应链管理系统、客户关系管理系统、人力资源管理系统等工业软件系统"},{"k":"D","t":"丁公司的生产车间开展工艺革新，推动设备联网、生产环节数字化连接，强化标准作业、可视化管控、精准配送和最优库存，打造智能车间"}],"answer":"C","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20221112-017-解析-p05-492-812.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-c-20221112-017-解析-p06-51-138.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"根据我国《“十四五”智能制造发展规划》，下列不属于智能制造示范工厂建设行动内容的是（ ）。","options":[{"k":"A","t":"甲公司在推动人工智能、大数据、区块链和虚拟现实等新技术在车间内制造环节进行深度应用，探索“人工智能 ”等智能场景应用"},{"k":"B","t":"乙钢铁公司围绕设计、生产、管理、服务等环节开展智能化升级，强化精益生产，打造智能工厂"},{"k":"C","t":"丙公司开发企业资源计划系统、供应链管理系统、客户关系管理系统、人力资源管理系统等工业软件系统"},{"k":"D","t":"丁公司的生产车间开展工艺革新，推动设备联网、生产环节数字化连接，强化标准作业、可视化管控、精准配送和最优库存，打造智能车间"}],"material":"","explanation":"17\n\n本题考查政治常识。\n\n面对不断升级的智能制造发展需求，《“十四五”智能制造发展规划》专门部署了“智能制造示范工厂建设行动”，推动“场景一车间-工厂一供应链”的智能化改造，探索智能制造最佳实践的标准化、模块化、精准化的推广路径。\n\n智能制造示范工厂建设行动包括：\n\n①智能场景。推动数字李生、人工智能、5G、大数据、区块链、虚拟现实(VR)/增强现实(AR)/混合现实(MR)等新技术在制造环节的深度应用，探索形成一批“数字李生”+“人工智能+”“虚拟/增强/混合现实(XR)+”等智能场景。\n\n②智能车间。覆盖加工、检测、物流等环节，开展工艺改进和革新，推动设备联网和生产环节数字化连接，强化标准作业、可视管控、精准配送、最优库存，打造一批智能车间，实现生产数据贯通化、制造柔性化和管理智能化。\n\n③智能工厂。支持基础条件好的企业，围绕设计、生产、管理、服务等制造全过程开展智能化升级，优化组织结构和业务流程，强化精益生产，打造一批智能工厂，推动跨业务活动的数据共享和深度挖掘，实现对核心业务的精准预测、管理优化和自主决策。\n\n④智慧供应链。面向汽车、工程机械、轨道交通装备、航空航天装备、船舶与海洋工程装备、电力装备、医疗装备、家用电器、集成电路等行业，支持智能制造应用水平高、核心竞争优势突出、资源配置能力强的龙头企业建设供应链协同平台，打造数据互联互通、信息可信交互、生产深度协同、资源柔性配置的供应链。\n\n本题为选非题，故正确答案为C。"},"from":{"file":"07-事业编职测/C类/2022/2022-11-12/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"政治常识","questionPages":[4],"answerPages":[5,6]},"idx":16,"pid":"p2065d6d72f","sourceYears":[2022]}]};
